function protoReportSends(type) {
  return type === "extract" || type === "dcda";
}

function protoReportIsFile(type) {
  return protoReportSends(type) || type === "billing";
}

function protoReportPick(list, raw) {
  return (list.find((item) => item.id === raw) || list[0]).id;
}

function protoReportOptionName(list, id) {
  return (list.find((item) => item.id === id) || list[0]).name;
}

function protoReportTypeId(raw) {
  const id = String(raw || "");
  return PROTO_REPORT_TYPES.some((item) => item.id === id) ? id : "extract";
}

function protoReportType(raw) {
  const id = protoReportTypeId(raw);
  return PROTO_REPORT_TYPES.find((item) => item.id === id);
}

function protoReportPeriods() {
  return PROTO_REPORT_PERIODS;
}

function protoReportOnce(def) {
  return (protoReportSends(def?.type) || def?.type === "billing") && def?.period === "once";
}

// A bill covers each day in its date range, worked out for the next send.
function protoReportBillPeriod(def) {
  const period = protoReportPeriod("billing", def.period);
  const range = protoReportDataRange(def) || protoReportRangeAt({ ...def, rangeMode: "preset", rangePreset: "last-month" }, protoToday());
  return { ...period, name: protoReportRangeWords(def), days: protoReportRangeDays(range), from: range.from, to: range.to };
}

function protoReportBillCostWords(period) {
  return `cost for ${protoReportSpanWords(period)} is`;
}

// "1 Aug 2026 to 31 Aug 2026", or one date for a single day.
function protoReportSpanWords(range) {
  if (!range) return "";
  const from = protoFormatFullDay(range.from);
  return protoDayStamp(range.from) === protoDayStamp(range.to) ? from : `${from} to ${protoFormatFullDay(range.to)}`;
}

function protoReportRangeDays(range) {
  return Math.max(1, Math.round((range.to - range.from) / 86400000) + 1);
}

// How a report with no range yet starts: the period before each send.
function protoReportRangeFor(period) {
  const base = { rangeMode: "preset", rangePreset: "last-month", rangeCount: 3, rangeUnit: "month", rangeCurrent: false };
  if (period === "once") return { ...base, rangeMode: "dates" };
  if (period === "day") return { ...base, rangePreset: "yesterday" };
  if (period === "week") return { ...base, rangePreset: "last-week" };
  if (period === "quarter") return { ...base, rangeMode: "rolling" };
  if (period === "half") return { ...base, rangeMode: "rolling", rangeCount: 6 };
  return base;
}

// The from and to dates for a send on ref. This week, month and year run up to ref itself.
function protoReportRangeAt(def, ref) {
  if (def.rangeMode === "dates") return protoReportRange(def);
  const day = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
  const monday = protoAddDays(day, -((day.getDay() + 6) % 7));
  const month = (back) => new Date(day.getFullYear(), day.getMonth() - back, 1);
  const before = (date) => protoAddDays(date, -1);
  if (def.rangeMode === "rolling") {
    const n = Math.max(1, Math.round(Number(def.rangeCount) || 1));
    const now = Boolean(def.rangeCurrent);
    if (def.rangeUnit === "week") {
      return now ? { from: protoAddDays(monday, -7 * (n - 1)), to: day } : { from: protoAddDays(monday, -7 * n), to: before(monday) };
    }
    if (def.rangeUnit === "month") return now ? { from: month(n - 1), to: day } : { from: month(n), to: before(month(0)) };
    return now ? { from: protoAddDays(day, 1 - n), to: day } : { from: protoAddDays(day, -n), to: before(day) };
  }
  const year = day.getFullYear();
  switch (def.rangePreset) {
    case "yesterday":
      return { from: before(day), to: before(day) };
    case "this-week":
      return { from: monday, to: day };
    case "this-month":
      return { from: month(0), to: day };
    case "this-year":
      return { from: new Date(year, 0, 1), to: day };
    case "last-week":
      return { from: protoAddDays(monday, -7), to: before(monday) };
    case "last-year":
      return { from: new Date(year - 1, 0, 1), to: new Date(year - 1, 11, 31) };
    case "last-31":
      return { from: protoAddDays(day, -31), to: before(day) };
    case "last-12m":
      return { from: new Date(year - 1, day.getMonth(), day.getDate()), to: before(day) };
    default:
      return { from: month(1), to: before(month(0)) };
  }
}

// The range for a send. With no date given, the next send, or the Send on date for Once.
function protoReportDataRange(def, when) {
  const ref = when || (protoReportOnce(def) ? protoFromUkDate(def.start) : protoReportNextSend(def)) || protoToday();
  return protoReportRangeAt(def, ref);
}

// The days a sample file holds: the range as if it sent today, up to today.
function protoReportSampleDays(def) {
  const today = protoToday();
  const range = protoReportRangeAt(def, today);
  const days = [];
  if (!range) return days;
  const to = range.to > today ? today : range.to;
  for (let day = range.from; day <= to && days.length < 800; day = protoAddDays(day, 1)) days.push(day);
  days.splice(0, Math.max(0, days.length - PROTO_REPORT_FILE_DAYS));
  return days;
}

function protoReportRangeUnit(id) {
  return PROTO_REPORT_RANGE_UNITS.find((item) => item.id === id) || PROTO_REPORT_RANGE_UNITS[2];
}

// "Last month", "Last 3 months including this month" or "1 Aug 2026 to 31 Aug 2026".
function protoReportRangeWords(def) {
  if (def.rangeMode === "dates") {
    const range = protoReportRange(def);
    return range ? protoReportSpanWords(range) : "Exact dates";
  }
  if (def.rangeMode === "rolling") {
    const unit = protoReportRangeUnit(def.rangeUnit);
    const n = Math.max(1, Math.round(Number(def.rangeCount) || 1));
    return `Last ${n} ${n === 1 ? unit.one : unit.many}${def.rangeCurrent ? ` including ${unit.current}` : ""}`;
  }
  return protoReportOptionName(PROTO_REPORT_RANGE_PRESETS, def.rangePreset);
}

function protoReportDefaultRange() {
  const today = protoToday();
  const from = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const to = new Date(today.getFullYear(), today.getMonth(), 0);
  return { from: protoFormatUkDate(from), to: protoFormatUkDate(to) };
}

function protoReportRange(def) {
  const from = protoFromUkDate(def.from);
  const to = protoFromUkDate(def.to);
  return from && to ? { from, to } : null;
}

function protoReportPeriod(type, raw) {
  const list = protoReportPeriods(type);
  return list.find((item) => item.id === raw) || list.find((item) => item.id === (type === "billing" ? "month" : "week"));
}

function protoReportSilenceName(hours) {
  if (hours >= 24) {
    const days = Math.round(hours / 24);
    return `${days} ${days === 1 ? "day" : "days"}`;
  }
  return `${hours} ${hours === 1 ? "hour" : "hours"}`;
}

function protoReportDefaultName(type) {
  if (type === "billing") return "Tenant billing";
  if (type === "alert") return "Threshold alert";
  if (type === "missing") return "Missing data alert";
  if (type === "dcda") return "DC and DA reads";
  return "Interval data extract";
}

function protoCanEditReports() {
  return protoCanAct();
}

function protoCanAddReports() {
  return protoCanEditReports();
}

function protoReportDefsStore() {
  const raw = store.prototypeReportDefs;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
}

function protoReportDefsKey() {
  return String(protoCompanyId() || "company");
}

function protoReportSiteIds() {
  return protoEstateSites()
    .map((site) => protoSiteId(site))
    .filter(Boolean);
}

function protoReportSiteById(id) {
  return protoEstateSites().find((site) => protoSiteId(site) === id) || null;
}

// Groups a report can follow: All sites, each company for TPI and Supplier, then each Portfolio group.
// A report keeps the group, not a copy of its sites, so it follows sites added to or taken off the group.
function protoReportGroupList() {
  const groups = protoGroups()
    .map((group) => ({ id: group.id, name: group.name, sites: group.sites.filter((site) => !protoIsDummySite(site)) }))
    .filter((group) => group.sites.length);
  const all = { id: "all", name: "All sites", sites: groups.flatMap((group) => group.sites) };
  const companies = protoCompaniesFrom(groups).map((item) => ({ id: item.id, name: item.name, sites: item.sites }));
  return [all, ...companies, ...groups];
}

function protoReportGroupById(id) {
  return protoReportGroupList().find((group) => group.id === id) || null;
}

function protoReportMpans() {
  return protoReportMeterList().filter(({ meter }) => meter.mpan);
}

function protoReportMeterList() {
  return protoEstateSites().flatMap((site) => (site.meters || []).map((meter) => ({ site, meter })));
}

// Any meter, with or without an MPAN. Alerts pick gas sub meters too.
function protoReportMpanById(id) {
  return protoReportMeterList().find((item) => item.meter.id === id) || null;
}

// Alerts name a sub meter by site. Other reports name it by MPAN.
function protoReportMeterWords(hit, draft) {
  return draft?.type === "alert" || !hit.meter.mpan ? `${hit.site.name} · ${hit.meter.name}` : `MPAN ${hit.meter.mpan}`;
}

function protoReportPicksAny(def) {
  return Boolean(def?.sites?.length || def?.groups?.length || def?.meters?.length);
}

// Whole sites, picked one by one or through a group. A site reached only by an MPAN keeps just that meter.
function protoReportWholeSiteIds(def) {
  const ids = new Set((def.sites || []).map(String));
  (def.groups || []).forEach((id) =>
    (protoReportGroupById(id)?.sites || []).forEach((site) => ids.add(String(protoSiteId(site))))
  );
  return ids;
}

function protoReportPickedSiteIds(def) {
  const ids = protoReportWholeSiteIds(def);
  (def.meters || []).forEach((id) => {
    const hit = protoReportMpanById(id);
    if (hit) ids.add(String(protoSiteId(hit.site)));
  });
  return ids;
}

function protoReportScopeWords(draft) {
  const groups = (draft.groups || []).map(protoReportGroupById).filter(Boolean);
  const sites = draft.sites || [];
  const meters = draft.meters || [];
  const picks = groups.length + sites.length + meters.length;
  if (!picks) return "";
  const n = protoReportPickedSiteIds(draft).size;
  const siteWords = `${n} ${n === 1 ? "site" : "sites"}`;
  if (picks === 1 && groups.length) return `${groups[0].name} (${siteWords})`;
  if (picks === 1 && sites.length) return protoReportSiteById(sites[0])?.name || siteWords;
  if (!groups.length && !sites.length) {
    const hit = meters.length === 1 ? protoReportMpanById(meters[0]) : null;
    if (hit) return protoReportMeterWords(hit, draft);
    return `${meters.length} ${draft.type === "alert" ? "sub meters" : "MPANs"}`;
  }
  return siteWords;
}

// What each recipient can do with this report. It is separate from their role in Astral.
const PROTO_REPORT_ACCESS = [
  { id: "copy", name: "Gets a copy", note: "Email only" },
  { id: "edit", name: "Can edit", note: "Appears in their Reports and they can change it" },
];

function protoReportRoleDefault(key) {
  return key === "person:me" ? "edit" : "copy";
}

function protoReportRoles(raw) {
  const out = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  Object.entries(raw).forEach(([key, value]) => {
    const k = String(key);
    if (!/^(person|email):./.test(k)) return;
    if (!PROTO_REPORT_ACCESS.some((item) => item.id === value)) return;
    if (value !== protoReportRoleDefault(k)) out[k] = value;
  });
  return out;
}

function protoReportRoleOf(draft, key) {
  // People outside the organisation can only get the file by email.
  if (String(key).startsWith("email:")) return "copy";
  const role = draft?.roles?.[key];
  return PROTO_REPORT_ACCESS.some((item) => item.id === role) ? role : protoReportRoleDefault(key);
}

function protoReportRoleName(id) {
  return PROTO_REPORT_ACCESS.find((item) => item.id === id)?.name || PROTO_REPORT_ACCESS[0].name;
}

function protoReportEmails(raw) {
  const list = Array.isArray(raw) ? raw : String(raw || "").split(/[\s,;]+/);
  return [
    ...new Set(
      list
        .map((item) => String(item || "").trim())
        .filter((item) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(item))
    ),
  ].slice(0, 20);
}

function protoReportNumber(raw, fallback, min, max) {
  const n = Number(raw);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
}

// Electricity and gas split usage into on-peak and off-peak. Water has one unit rate, so one usage share.
function protoReportUtilShareKeys(util) {
  return util.id === "water"
    ? [`${util.id}Standing`, `${util.id}Usage`]
    : [`${util.id}Standing`, `${util.id}OnPeak`, `${util.id}OffPeak`];
}

function protoReportShareKeys() {
  return PROTO_REPORT_BILL_UTILS.flatMap(protoReportUtilShareKeys);
}

// A tenant saved with one usage share takes it for on-peak and off-peak.
function protoReportShareLegacy(item, key) {
  return item[key] ?? item[key.replace(/(OnPeak|OffPeak)$/, "Usage")];
}

function protoReportTenantPeakFill(tenant) {
  const missing = protoReportShareKeys().filter((key) => !(key in tenant));
  if (!missing.length) return tenant;
  return {
    ...tenant,
    ...Object.fromEntries(missing.map((key) => [key, String(protoReportShareLegacy(tenant, key) ?? "")])),
  };
}

// A billing report bills one tenant on one site. The tenant sits in a list of one, so older reports still open.
function protoReportNormalizeTenants(raw, known) {
  const legacy = raw.tenant || raw.tenantEmail || raw.site;
  const list = Array.isArray(raw.tenants)
    ? raw.tenants
    : legacy
      ? [
          {
            id: "tenant-1",
            site: raw.site,
            name: raw.tenant,
            email: raw.tenantEmail,
            share: raw.share,
            ...Object.fromEntries(protoReportShareKeys().map((key) => [key, protoReportShareLegacy(raw, key)])),
          },
        ]
      : [];
  return list
    .filter((item) => item && typeof item === "object")
    .slice(0, 1)
    .map((item, i) => {
      const share = protoReportNumber(item.share ?? 50, 50, 0, 100);
      const vat = protoReportNumber(raw.vat ?? 20, 20, 0, 100);
      return {
        id: String(item.id || `tenant-${i + 1}`),
        site: known.has(String(item.site || "")) ? String(item.site) : "",
        name: String(item.name || "").replace(/\s+/g, " ").trim().slice(0, 80),
        email: protoReportEmails(String(item.email || "")).join(", "),
        ...Object.fromEntries(
          protoReportShareKeys().map((key) => [
            key,
            protoReportNumber(protoReportShareLegacy(item, key) ?? share, share, 0, 100),
          ])
        ),
        ...Object.fromEntries(PROTO_REPORT_BILL_UTILS.map((util) => [`${util.id}Pays`, item[`${util.id}Pays`] !== false])),
        taxes: protoReportNormalizeTaxes(item, vat),
      };
    });
}

// Each tenant has one tax, a name and a rate. A tenant saved with only a VAT rate opens as VAT.
// incl says the site rates already include the tax, so it is taken out of them rather than added.
function protoReportNormalizeTaxes(item, fallback) {
  const list = Array.isArray(item.taxes)
    ? item.taxes
    : [{ id: "tax-1", name: "VAT", rate: item.vat ?? fallback }];
  return list
    .filter((tax) => tax && typeof tax === "object")
    .slice(0, 1)
    .map((tax, i) => ({
      id: String(tax.id || `tax-${i + 1}`),
      name: String(tax.name ?? "").replace(/\s+/g, " ").trim().slice(0, 40),
      rate: protoReportNumber(tax.rate, 0, 0, 100),
      incl: tax.incl === true,
    }));
}

function protoReportTenantDraft(tenant) {
  return {
    ...tenant,
    ...Object.fromEntries(protoReportShareKeys().map((key) => [key, String(tenant[key] ?? "")])),
    taxes: (tenant.taxes || []).map((tax) => ({ ...tax, rate: String(tax.rate ?? "") })),
  };
}

// A draft saved before tenants became a list still opens.
function protoReportTenantsOf(draft) {
  if (Array.isArray(draft?.tenants)) {
    // Tenants drafted before taxes moved onto each tenant take VAT at the old rate.
    const keys = protoReportShareKeys();
    if (draft.tenants.every((tenant) => Array.isArray(tenant.taxes) && keys.every((key) => key in tenant))) {
      return draft.tenants;
    }
    return draft.tenants.map((tenant) =>
      protoReportTenantPeakFill(
        Array.isArray(tenant.taxes)
          ? tenant
          : { ...tenant, taxes: [{ id: "tax-1", name: "VAT", rate: String(tenant.vat ?? draft.vat ?? 20) }] }
      )
    );
  }
  if (draft?.type !== "billing") return [];
  return protoReportNormalizeTenants(draft, new Set(protoReportSiteIds())).map(protoReportTenantDraft);
}

function protoReportBlankTenant() {
  const [tenant] = protoReportNormalizeTenants(
    { tenants: [{ id: `tenant-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`, share: 100 }] },
    new Set()
  );
  return protoReportTenantDraft(tenant);
}

// Reports saved before the Date range tab keep the period before each send, or their Data from and Data to.
function protoReportRangeOf(raw, period) {
  const base = protoReportRangeFor(period);
  const mode = PROTO_REPORT_RANGE_MODES.some((item) => item.id === raw.rangeMode) ? raw.rangeMode : base.rangeMode;
  return {
    rangeMode: mode,
    rangePreset: PROTO_REPORT_RANGE_PRESETS.some((item) => item.id === raw.rangePreset) ? raw.rangePreset : base.rangePreset,
    rangeCount: Math.round(protoReportNumber(raw.rangeCount, base.rangeCount, 1, PROTO_REPORT_RANGE_MAX)),
    rangeUnit: PROTO_REPORT_RANGE_UNITS.some((item) => item.id === raw.rangeUnit) ? raw.rangeUnit : base.rangeUnit,
    rangeCurrent: raw.rangeCurrent == null ? base.rangeCurrent : Boolean(raw.rangeCurrent),
  };
}

function protoReportNormalize(raw) {
  if (!raw || typeof raw !== "object") return null;
  const type = protoReportTypeId(raw.type);
  const ids = protoReportSiteIds();
  const known = new Set(ids);
  const sites = [...new Set((Array.isArray(raw.sites) ? raw.sites : []).map(String))].filter((id) =>
    known.has(id)
  );
  const groupIds = new Set(protoReportGroupList().map((group) => group.id));
  const groups = [...new Set((Array.isArray(raw.groups) ? raw.groups : []).map(String))].filter((id) => groupIds.has(id));
  const meterIds = new Set(protoReportMeterList().map((item) => item.meter.id));
  const meters = [...new Set((Array.isArray(raw.meters) ? raw.meters : []).map(String))].filter((id) => meterIds.has(id));
  const start = protoMaskUkDate(raw.start || "");
  const range = protoReportDefaultRange();
  const from = protoMaskUkDate(raw.from || "");
  const to = protoMaskUkDate(raw.to || "");
  // FTP is gone. Reports saved with it send by SFTP to the same server.
  const asked = (Array.isArray(raw.delivery) ? raw.delivery : ["email"]).map((way) => (way === "ftp" ? "sftp" : way));
  const delivery = PROTO_REPORT_DELIVERY.map((item) => item.id).filter((id) => asked.includes(id));
  const def = {
    id: String(raw.id || `report-${Date.now()}`),
    type,
    name: String(raw.name || "").replace(/\s+/g, " ").trim().slice(0, 80) || protoReportDefaultName(type),
    on: raw.on !== false,
    start: protoFromUkDate(start) ? start : protoFormatUkDate(protoToday()),
    from: protoFromUkDate(from) ? from : range.from,
    to: protoFromUkDate(to) ? to : range.to,
    people: [...new Set((Array.isArray(raw.people) ? raw.people : []).map(String).filter(Boolean))],
    teams: [...new Set((Array.isArray(raw.teams) ? raw.teams : []).map(String))].filter((id) =>
      protoVisibleTeams().some((team) => team.id === id)
    ),
    emails: protoReportEmails(raw.emails),
    roles: protoReportRoles(raw.roles),
    sites,
    groups,
    meters,
    period: protoReportPeriod(type, raw.period).id,
    ...protoReportRangeOf(raw, protoReportPeriod(type, raw.period).id),
    ...protoReportSendDayOf(raw, start),
    delivery: delivery.length ? delivery : ["email"],
    content: protoReportPick(PROTO_REPORT_CONTENT, raw.content),
    utility: protoReportUtilityIds(raw.utility, type),
    channel: protoReportPick(PROTO_REPORT_CHANNEL, raw.channel),
    quality: protoReportPick(PROTO_REPORT_QUALITY, raw.quality),
    format: protoReportPick(PROTO_REPORT_FORMAT, raw.format === "xls" ? "xlsx" : raw.format),
    time: protoReportPick(PROTO_REPORT_TIME, raw.time),
    sendAt:
      raw.sendAt === "now" && protoReportPeriod(type, raw.period).id === "once"
        ? "now"
        : PROTO_REPORT_SEND_AT.includes(String(raw.sendAt))
          ? String(raw.sendAt)
          : "09:00",
    fileStart: String(raw.fileStart || "").trim().slice(0, 60),
    filePrefix: PROTO_REPORT_FILE_PREFIXES.some((item) => item.id === raw.filePrefix)
      ? raw.filePrefix
      : String(raw.fileStart || "").trim()
        ? "custom"
        : "none",
    fileSuffix: PROTO_REPORT_FILE_SUFFIXES.some((item) => item.id === raw.fileSuffix) ? raw.fileSuffix : "none",
    fileDate: PROTO_REPORT_FILE_DATES.some((item) => item.id === raw.fileDate) ? raw.fileDate : "iso",
    fileSep: ["_", "-", " "].includes(raw.fileSep) ? raw.fileSep : "_",
    sftpHost: String(raw.sftpHost || "").trim().slice(0, 120),
    sftpPath: String(raw.sftpPath || "").trim().slice(0, 160),
    sftpPort: protoReportNumber(raw.sftpPort, 22, 1, 65535),
    sftpUser: String(raw.sftpUser || "").trim().slice(0, 80),
    sftpAuth: raw.sftpAuth === "key" ? "key" : "password",
    sftpPassword: String(raw.sftpPassword || "").slice(0, 120),
    sftpFingerprint: String(raw.sftpFingerprint || "").trim().slice(0, 120),
    attach: raw.attach !== false,
    bySite: raw.bySite !== false,
    tenants: type === "billing" ? protoReportNormalizeTenants(raw, known) : [],
    vat: protoReportNumber(raw.vat, 20, 0, 100),
    basis: raw.basis === "absolute" ? "absolute" : "average",
    direction: raw.direction === "below" ? "below" : "above",
    priority: protoReportPick(PROTO_REPORT_PRIORITY, raw.priority || "medium"),
    levels: protoReportLevelIds(raw.levels),
    emailSubject: String(raw.emailSubject || "").replace(/\s+/g, " ").trim().slice(0, PROTO_REPORT_EMAIL_MAX.subject),
    emailPreview: String(raw.emailPreview || "").replace(/\s+/g, " ").trim().slice(0, PROTO_REPORT_EMAIL_MAX.preview),
    emailBody: String(raw.emailBody || "").replace(/\r\n?/g, "\n").trim().slice(0, PROTO_REPORT_EMAIL_MAX.body),
    notify: (() => {
      const list = PROTO_REPORT_NOTIFY.map((item) => item.id).filter((id) =>
        (Array.isArray(raw.notify) ? raw.notify : ["astral", "email"]).includes(id)
      );
      return Array.isArray(raw.notify) ? list : ["astral", "email"];
    })(),
    amount: protoReportNumber(raw.amount, 2000, 0, 10000000),
    percent: protoReportNumber(raw.percent, 25, 0, 1000),
    hours: protoReportSilenceHours(raw),
    owner: String(raw.owner || protoProfileEmail()),
    template: "",
    step: PROTO_TEMPLATE_STEPS.some((item) => item.id === raw.step) ? String(raw.step) : "",
  };
  // A report keeps its template. What IMSERV fixed follows the template from the next send.
  const tpl = type === "extract" && raw.template ? protoTemplate(String(raw.template)) : null;
  if (tpl && !tpl.builtIn) def.template = tpl.id;
  const rule = def.template ? tpl : protoTemplateBuiltIn(type);
  if (rule) {
    ["utility", "channel", "quality", "format"].forEach((key) => {
      if (rule.settings[key]?.mode === "fixed") def[key] = rule.settings[key].value;
    });
    def.utility = protoReportUtilityIds(def.utility, def.type);
    if (def.template) {
      def.content = "interval";
      def.step = protoTemplateStepOf(rule, def);
    }
  }
  // Reports saved before the consent tick keep the list they already had.
  def.consentFor = Array.isArray(raw.consentFor)
    ? [...new Set(raw.consentFor.map(String))]
    : protoReportConsentKeys(def);
  // Saved before the server and data joined consent, so they count as agreed.
  if (Array.isArray(raw.consentFor) && !def.consentFor.some((key) => key.startsWith("data:"))) {
    def.consentFor = [
      ...new Set([...def.consentFor, ...protoReportConsentKeys(def).filter((key) => !protoReportIsPersonKey(key))]),
    ];
  }
  return def;
}

