function protoHome() {
  const facts = protoHomeFacts();
  const kind = protoLens().home;
  let inner = protoHomeEstate(facts);
  if (kind === "broker") inner = protoHomeBroker(facts);
  else if (kind === "supplier") inner = protoHomeSupplier(facts);
  else if (kind === "admin") inner = protoHomeAdmin(facts);
  else if (kind === "owner") inner = protoHomeOwner(facts);
  else if (kind === "owner-super") inner = protoHomeOwnerSuper(facts);
  else if (kind === "finance") inner = protoHomeFinance(facts);
  else if (kind === "asset") inner = protoHomeAsset(facts);
  else if (kind === "data") inner = protoHomeData(facts);
  else if (kind === "exceptions") inner = protoHomeExceptions(facts);
  return astralShell(inner);
}

function protoSiteMatches(site, q) {
  if (!q) return true;
  const hay = [
    site.name,
    ...site.meters.map((item) => `${item.name} ${item.mpan || ""} ${item.mprn || ""} ${item.serial || ""}`),
  ]
    .join(" ")
    .toLowerCase();
  return hay.includes(q);
}

function protoTreeFilterIds() {
  const raw = Array.isArray(store.prototypeTreeFilters) ? store.prototypeTreeFilters : [];
  return raw.filter((id) => PROTO_TREE_FILTER_IDS.includes(id));
}

function protoPaneFilterIds() {
  const raw = Array.isArray(store.prototypePaneFilters) ? store.prototypePaneFilters : [];
  return raw.filter(
    (id) =>
      PROTO_PANE_FILTER_IDS.includes(id) &&
      id !== "in" &&
      id !== "out" &&
      id !== "electricity" &&
      id !== "gas" &&
      id !== "water"
  );
}

function protoPaneEffectiveFilterIds() {
  const pane = protoPaneFilterIds();
  const kinds = protoPaneMeterKindIds();
  if (kinds) {
    return kinds.length ? [...pane, ...kinds] : [...pane, "__none__"];
  }
  const treeMeters = protoPickedInGroup(protoTreeFilterIds(), "meter");
  return treeMeters.length ? [...pane, ...treeMeters] : pane;
}

function protoPaneFilterOpen() {
  return Boolean(store.prototypePaneFilterOpen);
}

function protoMetersVisible(meters, picked) {
  const ids = Array.isArray(picked) ? picked : [];
  if (ids.includes("__none__")) return [];
  const meterPicks = protoPickedInGroup(ids, "meter");
  return (meters || []).filter((item) => protoMeterKindOn(protoMeterKind(item), meterPicks));
}

// Meters a site has, for counts. Graphs leave water out by default because m³ cannot share a kWh axis, but a count must not.
function protoMetersListed(meters, picked) {
  const ids = Array.isArray(picked) ? picked : [];
  if (ids.includes("__none__")) return [];
  return protoPickedInGroup(ids, "meter").length ? protoMetersVisible(meters, ids) : meters || [];
}

function protoSitesForPane(sites) {
  const picked = protoPaneEffectiveFilterIds();
  return (sites || [])
    .filter((site) => protoSitePassesFilter(site, picked))
    .map((site) => ({
      ...site,
      listed: protoMetersListed(site.meters, picked),
      meters: protoMetersVisible(site.meters, picked),
    }))
    .filter((site) => site.meters.length);
}

function protoMetersForPane(meters) {
  return protoMetersVisible(meters, protoPaneEffectiveFilterIds());
}

function protoPaneAlerts(alerts) {
  const picked = protoPaneEffectiveFilterIds();
  return (alerts || []).filter((item) => {
    const meter = protoMeter(item.meterId);
    if (meter) return protoMeterPassesFilter(meter, picked);
    return protoSitePassesFilter(protoSiteByMeter(item.meterId), picked);
  });
}

function protoPaneQueries(rows) {
  const picked = protoPaneEffectiveFilterIds();
  return (rows || []).filter((row) => {
    const meter = protoMeter(row.meterId);
    if (meter) return protoMeterPassesFilter(meter, picked);
    return protoSitePassesFilter(protoSiteByMeter(row.meterId), picked);
  });
}

function protoTreeFilterOn() {
  return protoTreeFilterIds().length > 0;
}

function protoTreeFilterOpen() {
  return Boolean(store.prototypeTreeFilterOpen);
}

function protoFilterItemIds(groupId) {
  const group =
    PROTO_PANE_FILTERS.find((row) => row.id === groupId) ||
    PROTO_TREE_FILTERS.find((row) => row.id === groupId);
  return (group?.items || []).map((item) => item.id);
}

function protoPickedInGroup(picked, groupId) {
  return protoFilterItemIds(groupId).filter((id) => picked.includes(id));
}

function protoPickedPasses(picked, flags, meters) {
  const ids = Array.isArray(picked) ? picked : [];
  if (ids.includes("__none__")) return false;
  const list = meters || [];
  const meterPicks = protoPickedInGroup(ids, "meter");
  if (list.length) {
    const hit = list.some((item) => protoMeterKindOn(protoMeterKind(item), meterPicks));
    if (!hit) return false;
  }
  if (!ids.length) return true;
  const flow = protoPickedInGroup(ids, "flow");
  if (flow.length) {
    const hit = list.some((item) => {
      const out = item.direction === "Export";
      return (flow.includes("out") && out) || (flow.includes("in") && !out);
    });
    if (!hit) return false;
  }
  return true;
}

function protoSitePassesFilter(site, picked) {
  const ids = Array.isArray(picked) ? picked : protoTreeFilterIds();
  return protoPickedPasses(ids, protoSiteFlagWords(site), site?.meters || []);
}

function protoMeterPassesFilter(meter, picked) {
  const ids = Array.isArray(picked) ? picked : protoCompareFilterIds();
  return protoPickedPasses(ids, protoMeterFlagWords(meter), meter ? [meter] : []);
}

function protoGroupPassesFilter(group, picked) {
  const ids = Array.isArray(picked) ? picked : protoCompareFilterIds();
  return (group?.sites || []).some((site) => protoSitePassesFilter(site, ids));
}

function protoTreeFilterName(id) {
  for (const group of [...PROTO_TREE_FILTERS, ...PROTO_PANE_FILTERS]) {
    const item = group.items.find((row) => row.id === id);
    if (item) return item.name;
  }
  return "";
}

function protoFilterMeterKind(id) {
  const raw = String(id || "").trim().toLowerCase();
  if (raw === "water") return "water";
  if (raw === "gas") return "gas";
  if (raw === "electricity") return "electricity";
  return "";
}

function protoMarkFace(mark, name) {
  return `<span class="astral-filter-face">${protoTypeBadge(mark)}<span>${escapeHtml(name)}</span></span>`;
}

function protoFilterFace(id, label) {
  const name = label || protoTreeFilterName(id) || id;
  // Only the In and Out ticks are flows. A Data export in Downloads is not.
  const flow = id === "in" || id === "out" ? id : "";
  if (flow) return protoFlowMark(flow);
  const meter = protoFilterMeterKind(id);
  if (meter) {
    return `<span class="astral-filter-face">${protoIconMark(
      meter,
      "astral-meter-mark"
    )}<span>${escapeHtml(name)}</span></span>`;
  }
  return `<span>${escapeHtml(name)}</span>`;
}

let protoFilterPoolCache = null;

function protoFilterPool(attr) {
  if (attr !== "data-proto-pane-filter" && attr !== "data-proto-tree-filter") return null;
  if (!protoFilterPoolCache) {
    protoFilterPoolCache = new Map();
    queueMicrotask(() => {
      protoFilterPoolCache = null;
    });
  }
  if (!protoFilterPoolCache.has(attr)) {
    const meters =
      attr === "data-proto-pane-filter"
        ? protoPanePoolMeters() || []
        : protoSites().flatMap((site) => site.meters || []);
    protoFilterPoolCache.set(attr, meters);
  }
  return protoFilterPoolCache.get(attr);
}

const PROTO_FILTER_COUNTED = new Set(["electricity", "gas", "water", "in", "out"]);

function protoFilterMeterHit(id, meter) {
  if (id === "electricity" || id === "gas" || id === "water") return protoMeterKind(meter) === id;
  if (id === "out") return meter.direction === "Export";
  if (id === "in") return meter.direction !== "Export";
  return null;
}

// Every Filter shows how many rows each tick would leave, and greys a tick with none.
function protoFilterItemCount(attr, item) {
  if (attr === "data-proto-report-filter") return protoReportFilterCount(item?.id);
  if (attr === "data-proto-alert-filter") return item?.id ? protoAlertFilterCount(item.id) : null;
  if (attr === "data-proto-download-filter") {
    const rows = protoDownloadCountRows || protoDownloads();
    return item?.id ? rows.filter((row) => protoDownloadMatches(row, "", [item.id])).length : null;
  }
  if (attr === "data-proto-user-filter") {
    return item?.id ? protoUserPeople().filter((person) => person.role === item.id).length : null;
  }
  if (attr === "data-proto-compare-filter") {
    return item?.id && PROTO_FILTER_COUNTED.has(item.id) ? protoComparePeerCount(item.id) : null;
  }
  const pool = protoFilterPool(attr);
  const id = item?.id;
  if (!pool || !id || !PROTO_FILTER_COUNTED.has(id)) return null;
  if (attr === "data-proto-tree-filter") {
    return protoSites().filter((site) => (site.meters || []).some((meter) => protoFilterMeterHit(id, meter)))
      .length;
  }
  return pool.filter((meter) => protoFilterMeterHit(id, meter)).length;
}

const PROTO_HOURS_KIND = { "hours-on": "on", "hours-non": "non", "hours-off": "closed" };
let protoHoursKindCache = null;

function protoMeterHasHourKind(meter, kind) {
  const rows = protoMeterProfile(meter?.id).hours || [];
  return (rows.length ? rows : [null]).some((row) => {
    for (let i = 0; i < 48; i += 1) {
      if (protoHourKind(meter, i / 2, row || undefined) === kind) return true;
    }
    return false;
  });
}

function protoPaneHasHourKind(id) {
  const kind = PROTO_HOURS_KIND[id];
  if (!kind) return true;
  if (!protoHoursKindCache) {
    protoHoursKindCache = new Map();
    queueMicrotask(() => {
      protoHoursKindCache = null;
    });
  }
  if (!protoHoursKindCache.has(id)) {
    protoHoursKindCache.set(
      id,
      (protoPanePoolMeters() || []).some((meter) => protoMeterHasHourKind(meter, kind))
    );
  }
  return protoHoursKindCache.get(id);
}

function protoFilterItemAvailable(attr, item) {
  if (
    attr === "data-proto-pane-filter" &&
    PROTO_PANE_KIND_IDS.includes(item?.id) &&
    (protoPaneMeterKindIds() || []).includes(item.id)
  ) {
    return true;
  }
  if (attr === "data-proto-pane-filter" && PROTO_HOURS_KIND[item?.id]) {
    return protoPaneHasHourKind(item.id);
  }
  const n = protoFilterItemCount(attr, item);
  return n === null || n > 0;
}

function protoFilterItemOn(attr, picked, item) {
  const id = item?.id;
  if (!id) return false;
  if (!protoFilterItemAvailable(attr, item)) return false;
  if (attr === "data-proto-pane-filter" && (id === "in" || id === "out")) {
    return (protoChartFlowSingle() || Array.isArray(store.prototypeChartFlows)) && protoChartFlowOn(id);
  }
  if (attr === "data-proto-pane-filter" && (id === "electricity" || id === "gas" || id === "water")) {
    return (protoPaneMeterKindIds() || []).includes(id);
  }
  return (picked || []).includes(id);
}

function protoFilterGroupTickState(group, attr, picked) {
  const items = (group?.items || []).filter((item) => protoFilterItemAvailable(attr, item));
  if (!items.length) return "off";
  let n = 0;
  items.forEach((item) => {
    if (protoFilterItemOn(attr, picked, item)) n += 1;
  });
  if (!n) return "off";
  if (n === items.length) return "on";
  return "mix";
}

function protoFilterGroupSelectNext(picked, group, allOn, attr) {
  const ids = (group?.items || [])
    .filter((item) => !attr || protoFilterItemAvailable(attr, item))
    .map((item) => item.id);
  const cur = Array.isArray(picked) ? picked : [];
  if (allOn) return cur.filter((id) => !ids.includes(id));
  return [...cur.filter((id) => !ids.includes(id)), ...ids];
}

function protoPanePoolMeterKinds() {
  return ["electricity", "gas", "water"].filter((kind) =>
    protoPanePoolMeters().some((item) => protoMeterKind(item) === kind)
  );
}

function protoTogglePaneFilterGroup(groupId) {
  const group = PROTO_PANE_FILTERS.find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoPaneFilterIds();
  const selectAll = protoFilterGroupTickState(group, "data-proto-pane-filter", picked) !== "on";
  const patch = {
    prototypePaneFilterOpen: true,
    prototypeChartPoint: null,
  };
  if (groupId === "meter") {
    patch.prototypePaneMeterKinds = selectAll ? protoPanePoolMeterKinds() : null;
  } else if (groupId === "flow") {
    if (protoChartFlowSingle()) return;
    patch.prototypeChartFlows = selectAll ? ["in", "out"] : null;
  } else {
    patch.prototypePaneFilters = protoFilterGroupSelectNext(
      picked,
      group,
      !selectAll,
      "data-proto-pane-filter"
    ).filter((id) =>
      PROTO_PANE_FILTER_IDS.includes(id)
    );
  }
  setProto(patch);
  protoRestoreFocus(`#astral-pane-filter-menu [data-proto-pane-filter-all="${CSS.escape(groupId)}"]`);
}

function protoToggleTreeFilterGroup(groupId) {
  const group = PROTO_TREE_FILTERS.find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoTreeFilterIds();
  const selectAll = protoFilterGroupTickState(group, "data-proto-tree-filter", picked) !== "on";
  setProto({
    prototypeTreeFilterOpen: true,
    prototypeTreeFilters: protoFilterGroupSelectNext(
      picked,
      group,
      !selectAll,
      "data-proto-tree-filter"
    ).filter((id) =>
      PROTO_TREE_FILTER_IDS.includes(id)
    ),
  });
  protoRestoreFocus(`#astral-tree-filter-menu [data-proto-tree-filter-all="${CSS.escape(groupId)}"]`);
}

function protoToggleCompareFilterGroup(groupId) {
  const group = PROTO_TREE_FILTERS.find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoCompareFilterIds();
  const selectAll = protoFilterGroupTickState(group, "data-proto-compare-filter", picked) !== "on";
  setProto({
    prototypeCompareFilterOpen: true,
    prototypeCompareFilters: protoFilterGroupSelectNext(picked, group, !selectAll).filter((id) =>
      PROTO_TREE_FILTER_IDS.includes(id)
    ),
  });
  protoRestoreFocus(`#astral-compare-filter-menu [data-proto-compare-filter-all="${CSS.escape(groupId)}"]`);
}

function protoToggleDownloadFilterGroup(groupId) {
  const group = protoDownloadFilterGroups().find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoDownloadPicked();
  const selectAll = protoFilterGroupTickState(group, "data-proto-download-filter", picked) !== "on";
  setProto({
    prototypeDownloadFilterOpen: true,
    prototypeDownloadFilters: protoDownloadFilterIds(
      protoFilterGroupSelectNext(picked, group, !selectAll)
    ),
  });
  protoRestoreFocus(`#astral-download-filter-menu [data-proto-download-filter-all="${CSS.escape(groupId)}"]`);
}

function protoToggleReportFilterGroup(groupId) {
  const group = protoReportFilterGroups().find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoReportFilterIds();
  const selectAll = protoFilterGroupTickState(group, "data-proto-report-filter", picked) !== "on";
  setProto({
    prototypeReportFilterOpen: true,
    prototypeReportFilters: protoReportFilterIds(
      protoFilterGroupSelectNext(picked, group, !selectAll, "data-proto-report-filter")
    ),
  });
  protoRestoreFocus(`#astral-report-filter-menu [data-proto-report-filter-all="${CSS.escape(groupId)}"]`);
}

function protoToggleUserFilterGroup(groupId) {
  const group = protoUserFilterGroups().find((row) => row.id === groupId);
  if (!group) return;
  const picked = protoUserRoleFilterIds();
  const selectAll = protoFilterGroupTickState(group, "data-proto-user-filter", picked) !== "on";
  setProto({
    prototypeUserRoleFilterOpen: true,
    prototypeUserRoleFilter: protoUserRoleFilterIds(
      protoFilterGroupSelectNext(picked, group, !selectAll)
    ),
  });
  protoRestoreFocus(`#astral-user-filter-menu [data-proto-user-filter-all="${CSS.escape(groupId)}"]`);
}

const PROTO_FILTER_MENU_IDS = {
  "data-proto-tree-filter": "astral-tree-filter-menu",
  "data-proto-pane-filter": "astral-pane-filter-menu",
  "data-proto-compare-filter": "astral-compare-filter-menu",
  "data-proto-download-filter": "astral-download-filter-menu",
  "data-proto-report-filter": "astral-report-filter-menu",
  "data-proto-alert-filter": "astral-alert-filter-menu",
  "data-proto-user-filter": "astral-user-filter-menu",
};

let protoFilterSectionOpen = "";

function protoFilterSectionKey(menuId, groupId) {
  return `${menuId}:${groupId}`;
}

function protoFilterSectionDom(key) {
  return [...document.querySelectorAll("[data-proto-filter-section]")].find(
    (node) => node.dataset.protoFilterSection === key
  );
}

function protoFilterSectionOnItems(group, attr, picked) {
  return (group?.items || []).filter((item) => protoFilterItemOn(attr, picked, item));
}

function protoFilterSectionAllOn(group, attr, on) {
  const avail = (group?.items || []).filter((item) => protoFilterItemAvailable(attr, item));
  return on.length > 1 && on.length === avail.length;
}

function protoFilterSectionSummary(group, attr, picked) {
  if (!(group?.items || []).some((item) => protoFilterItemAvailable(attr, item))) {
    return "None in this view";
  }
  const on = protoFilterSectionOnItems(group, attr, picked);
  if (!on.length) return "None selected";
  if (protoFilterSectionAllOn(group, attr, on)) return "All";
  return on.map((item) => item.name).join(", ");
}

function protoFilterSectionPills(group, attr, picked) {
  const on = protoFilterSectionOnItems(group, attr, picked);
  if (!on.length || protoFilterSectionAllOn(group, attr, on)) return "";
  const pills = on
    .map(
      (item) =>
        `<span class="astral-filter-pill astral-filter-section-pill">${protoFilterFace(
          item.id,
          item.name
        )}</span>`
    )
    .join("");
  return `<span class="astral-filter-section-pills">${pills}</span>`;
}

function protoFilterSection(key, name, summary, body, face = "") {
  const open = protoFilterSectionOpen === key;
  const id = `astral-filter-section-${String(key).replace(/[^a-z0-9_-]+/gi, "-")}`;
  return `
    <div
      class="astral-filter-group astral-filter-section${open ? " is-open" : ""}"
      data-proto-filter-section="${escapeHtml(key)}"
    >
      <p id="${escapeHtml(id)}-label">${escapeHtml(name)}</p>
      <button
        type="button"
        class="astral-select-btn astral-filter-section-btn"
        aria-haspopup="true"
        aria-expanded="${open ? "true" : "false"}"
        aria-controls="${escapeHtml(id)}"
        aria-label="${escapeHtml(`${name}: ${summary}`)}"
        data-proto-filter-section-toggle="${escapeHtml(key)}"
      >
        ${face || `<span>${escapeHtml(summary)}</span>`}
        ${protoChevronMark("menu")}
      </button>
      ${protoFoldClip(
        open,
        id,
        `<div class="astral-filter-section-list" role="group" aria-labelledby="${escapeHtml(
          id
        )}-label">${body}</div>`
      )}
    </div>
  `;
}

function protoFilterSectionsLive() {
  if (!protoFilterSectionOpen) return;
  const menuId = protoFilterSectionOpen.split(":")[0];
  if (!protoOpenMenuKeys().includes(menuId)) protoFilterSectionOpen = "";
}

function protoFilterSectionFollow(menu, until) {
  const step = () => {
    protoPlaceFloatMenus();
    if (performance.now() < until) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
  if (!menu) return;
  const reveal = () => {
    const open = menu.querySelector(".astral-filter-section.is-open");
    if (!open) return;
    const box = menu.getBoundingClientRect();
    const row = open.getBoundingClientRect();
    if (row.bottom > box.bottom - 8) {
      menu.scrollTop += Math.min(row.bottom - box.bottom + 8, row.top - box.top - 8);
    } else if (row.top < box.top) {
      menu.scrollTop -= box.top - row.top + 8;
    }
  };
  const clip = menu.querySelector(".astral-filter-section.is-open > .astral-fold-clip");
  if (clip) {
    clip.addEventListener("transitionend", reveal, { once: true });
    setTimeout(reveal, Math.max(0, until - performance.now()));
  }
}

function protoToggleFilterSection(key) {
  const next = protoFilterSectionOpen === key ? "" : key;
  const prev = protoFilterSectionOpen;
  protoFilterSectionOpen = next;
  [prev, next].filter(Boolean).forEach((item) => {
    const root = protoFilterSectionDom(item);
    if (!root) return;
    const open = item === next;
    const clip = root.querySelector(":scope > .astral-fold-clip");
    const from = protoFoldHeight(clip);
    root.classList.toggle("is-open", open);
    root
      .querySelector(":scope > .astral-filter-section-btn")
      ?.setAttribute("aria-expanded", open ? "true" : "false");
    clip?.setAttribute("aria-hidden", open ? "false" : "true");
    clip?.toggleAttribute("inert", !open);
    protoFoldMotion(clip, from, open);
  });
  const menu = protoFilterSectionDom(key)?.closest(".astral-filter-menu");
  const ms = matchMedia("(prefers-reduced-motion: reduce)").matches ? 0 : 420;
  protoFilterSectionFollow(menu, performance.now() + ms);
}

function protoFilterCountNoun(attr, count) {
  const one = count === 1;
  if (attr === "data-proto-tree-filter") return one ? "site" : "sites";
  if (attr === "data-proto-report-filter") {
    const alert = protoReportSheetTab() === "alerts";
    return alert ? (one ? "alert" : "alerts") : one ? "report" : "reports";
  }
  if (attr === "data-proto-download-filter") return one ? "file" : "files";
  if (attr === "data-proto-alert-filter") return one ? "flag" : "flags";
  if (attr === "data-proto-user-filter") return one ? "person" : "people";
  if (attr === "data-proto-compare-filter") {
    const level = protoCompareLevel();
    if (level === "group") return one ? "group" : "groups";
    if (level !== "meter") return one ? "site" : "sites";
  }
  return one ? "meter" : "meters";
}

// How many peers in Compare one tick would leave. Search does not change it.
function protoComparePeerCount(id) {
  const level = protoCompareLevel();
  if (level === "group") {
    return protoGroups().filter((group) => group.id !== store.prototypeGroup && protoGroupPassesFilter(group, [id]))
      .length;
  }
  if (level === "meter") {
    const currentId = protoCompareCurrentId();
    return protoPortfolioMeters().filter((row) => row.meter.id !== currentId && protoMeterPassesFilter(row.meter, [id]))
      .length;
  }
  const currentId = protoSiteId(protoSiteByMeter(store.activePrototypeMeter));
  return protoSites().filter(
    (site) =>
      protoSiteId(site) !== currentId &&
      protoSitePassesFilter(site, [id]) &&
      protoMetersVisible(site.meters, [id]).length
  ).length;
}

function protoFilterTickGroups(picked, attr, groups = PROTO_TREE_FILTERS) {
  const menuId = PROTO_FILTER_MENU_IDS[attr] || attr;
  return groups.map((group) => {
    const state = protoFilterGroupTickState(group, attr, picked);
    const allOn = state === "on";
    const mix = state === "mix";
    const checked = allOn ? "true" : mix ? "mixed" : "false";
    const usable = group.items.some((item) => protoFilterItemAvailable(attr, item));
    const single = attr === "data-proto-pane-filter" && group.id === "flow" && protoChartFlowSingle();
    const allBtn = single
      ? ""
      : `
      <button
        type="button"
        role="menuitemcheckbox"
        class="astral-filter-all${allOn ? " is-on" : ""}${mix ? " is-mix" : ""}${usable ? "" : " is-disabled"}"
        aria-checked="${checked}"
        aria-label="Select all ${escapeHtml(group.name)}"
        ${usable ? "" : `disabled aria-disabled="true"`}
        ${attr}-all="${escapeHtml(group.id)}"
      >
        <span class="astral-check${allOn ? " is-on" : ""}${mix ? " is-mix" : ""}" aria-hidden="true"></span>
        <span>All</span>
      </button>
    `;
    const options = group.items
      .map((item) => {
        const on = protoFilterItemOn(attr, picked, item);
        const avail = protoFilterItemAvailable(attr, item);
        const count = protoFilterItemCount(attr, item);
        const noun = protoFilterCountNoun(attr, count);
        const countHtml =
          count === null
            ? ""
            : `<span class="astral-filter-count" aria-label="${count} ${noun}">${count}</span>`;
        return `
          <button
            type="button"
            role="${single ? "menuitemradio" : "menuitemcheckbox"}"
            class="astral-filter-child${on ? " is-on" : ""}${avail ? "" : " is-disabled"}"
            aria-checked="${on ? "true" : "false"}"
            ${avail ? "" : `disabled aria-disabled="true" title="None in this view"`}
            ${attr}="${escapeHtml(item.id)}"
          >
            <span class="${single ? "astral-radio" : "astral-check"}${on ? " is-on" : ""}" aria-hidden="true"></span>
            ${item.mark ? protoMarkFace(item.mark, item.name) : protoFilterFace(item.id, item.name)}
            ${countHtml}
          </button>
        `;
      })
      .join("");
    return protoFilterSection(
      protoFilterSectionKey(menuId, group.id),
      group.name,
      protoFilterSectionSummary(group, attr, picked),
      `${allBtn}${options}`,
      protoFilterSectionPills(group, attr, picked)
    );
  }).join("");
}

function protoFilterPills(picked, attr) {
  const ids = picked || [];
  if (!ids.length) return "";
  const pills = ids
    .map((id) => {
      const name = protoTreeFilterName(id);
      return `
        <span class="astral-filter-pill">
          ${protoFilterFace(id)}
          ${protoClearButton(
            "astral-filter-pill-clear",
            `${attr}="${escapeHtml(id)}"`,
            `Clear ${name}`
          )}
        </span>
      `;
    })
    .join("");
  return `
    <div class="astral-filter-pills">
      ${pills}
      ${protoTextBtn("Clear", `${attr}="clear"`)}
    </div>
  `;
}

function protoTreeFilterControl() {
  const open = protoTreeFilterOpen();
  const picked = protoTreeFilterIds();
  return protoFilterShell({
    hit: `data-proto-tree-filter="toggle"`,
    open,
    count: picked.length,
    menuId: "astral-tree-filter-menu",
    clear: 'data-proto-tree-filter="clear"',
    canClear: picked.length > 0,
    menu: protoFilterTickGroups(picked, "data-proto-tree-filter"),
  });
}

function protoPaneFilterCount() {
  const attr = "data-proto-pane-filter";
  const picked = protoPaneFilterIds();
  return PROTO_PANE_FILTERS.reduce(
    (sum, group) =>
      sum +
      group.items.filter(
        (item) => protoFilterItemAvailable(attr, item) && protoFilterItemOn(attr, picked, item)
      ).length,
    0
  );
}

function protoPaneFilterControl() {
  const open = protoPaneFilterOpen();
  const picked = protoPaneFilterIds();
  const count = protoPaneFilterCount();
  return protoFilterShell({
    hit: `data-proto-pane-filter="toggle"`,
    open,
    count,
    menuId: "astral-pane-filter-menu",
    clear: 'data-proto-pane-filter="clear"',
    canClear:
      count > 0 ||
      protoPaneMeterKindIds() !== null ||
      Array.isArray(store.prototypeChartFlows) ||
      (store.prototypeChartSliceOff || []).length > 0,
    menu: protoFilterTickGroups(picked, "data-proto-pane-filter", PROTO_PANE_FILTERS),
  });
}

function protoTreeFilterPills() {
  return protoFilterPills(protoTreeFilterIds(), "data-proto-tree-filter");
}

function protoPaneFilterPills() {
  return "";
}

function protoCompareFilterIds() {
  const raw = Array.isArray(store.prototypeCompareFilters) ? store.prototypeCompareFilters : [];
  return raw.filter((id) => PROTO_TREE_FILTER_IDS.includes(id));
}

function protoCompareFilterOpen() {
  return Boolean(store.prototypeCompareFilterOpen);
}

function protoCompareSortChoices() {
  const level = protoCompareLevel();
  const items = [
    { id: "name", name: "Name" },
    { id: "action", name: "Needs action" },
  ];
  if (level !== "meter") {
    items.push({ id: "count", name: level === "group" ? "Sites" : protoBelowSiteHeading(2) });
  }
  return items;
}

function protoCompareSortId() {
  const ids = protoCompareSortChoices().map((item) => item.id);
  const raw = String(store.prototypeCompareSort || "name");
  return ids.includes(raw) ? raw : "name";
}

function protoCompareSortName(id) {
  return protoCompareSortChoices().find((item) => item.id === id)?.name || "";
}

function protoCompareFilterCount() {
  return protoCompareFilterIds().length + (protoCompareSortId() === "name" ? 0 : 1);
}

function protoCompareSortPeers(rows, getName, getCount, getWords) {
  const sort = protoCompareSortId();
  return [...rows].sort((a, b) => {
    if (sort === "action") {
      const diff = protoActionRank(getWords(a)) - protoActionRank(getWords(b));
      if (diff) return diff;
    } else if (sort === "count") {
      const diff = getCount(b) - getCount(a);
      if (diff) return diff;
    }
    return getName(a).localeCompare(getName(b), "en-GB");
  });
}

function protoCompareFilterControl() {
  const open = protoCompareFilterOpen();
  const picked = protoCompareFilterIds();
  const sort = protoCompareSortId();
  const sorts = protoCompareSortChoices()
    .map((item) => {
      const on = sort === item.id;
      return `
        <button
          type="button"
          role="menuitemradio"
          class="${on ? "is-on" : ""}"
          aria-checked="${on ? "true" : "false"}"
          data-proto-compare-sort="${escapeHtml(item.id)}"
        >
          <span class="astral-check${on ? " is-on" : ""}" aria-hidden="true"></span>
          <span>${escapeHtml(item.name)}</span>
        </button>
      `;
    })
    .join("");
  return protoFilterShell({
    hit: `data-proto-compare-filter="toggle"`,
    open,
    count: protoCompareFilterCount(),
    menuId: "astral-compare-filter-menu",
    clear: 'data-proto-compare-filter="clear"',
    canClear: protoCompareFilterCount() > 0,
    extraClass: "astral-compare-filter",
    menu: `${protoFilterTickGroups(picked, "data-proto-compare-filter")}
      ${protoFilterSection(
        protoFilterSectionKey("astral-compare-filter-menu", "sort"),
        "Sort",
        protoCompareSortName(sort),
        sorts
      )}`,
  });
}

function protoCompareFilterPills() {
  const picked = protoCompareFilterIds();
  const sort = protoCompareSortId();
  if (!picked.length && sort === "name") return "";
  const pills = [
    ...picked.map((id) => {
      const name = protoTreeFilterName(id);
      return `
        <span class="astral-filter-pill">
          ${protoFilterFace(id)}
          ${protoClearButton(
            "astral-filter-pill-clear",
            `data-proto-compare-filter="${escapeHtml(id)}"`,
            `Clear ${name}`
          )}
        </span>
      `;
    }),
    sort === "name"
      ? ""
      : `
        <span class="astral-filter-pill">
          <span>${escapeHtml(protoCompareSortName(sort))}</span>
          ${protoClearButton(
            "astral-filter-pill-clear",
            `data-proto-compare-sort="name"`,
            `Clear ${protoCompareSortName(sort)}`
          )}
        </span>
      `,
  ].join("");
  return `
    <div class="astral-filter-pills">
      ${pills}
      ${protoTextBtn("Clear", "data-proto-compare-filter=\"clear\"")}
    </div>
  `;
}

function protoEnglandOrg() {
  return protoOrgCountry() === "eng";
}

function protoBelowSiteNoun(count) {
  const n = Number(count);
  const plural = !Number.isFinite(n) || n !== 1;
  return plural ? "meter points" : "meter point";
}

function protoBelowSiteHeading(count) {
  const noun = protoBelowSiteNoun(count);
  return noun.charAt(0).toUpperCase() + noun.slice(1);
}

function protoMeterCountWords(n, meters) {
  const count = Number(n) || 0;
  return `${count} ${protoBelowSiteNoun(count)}`;
}

function protoSiteMeterNoun(meters) {
  return protoBelowSiteNoun((meters || []).length);
}

function protoSiteButton(site, on) {
  const listed = site.listed || site.meters;
  const n = listed.length;
  const noun = protoSiteMeterNoun(listed);
  const refs = listed.map((item) => protoMeterRef(item)).filter(Boolean);
  const tip = refs.length ? `${n} ${noun}. ${refs.join(". ")}` : `${n} ${noun}`;
  const count = n
    ? protoIconTip(`<span class="astral-count">${n}</span>`, tip)
    : "";
  return `
    <button
      type="button"
      class="astral-site${on ? " is-on" : ""}"
      data-proto-site="${escapeHtml(site.meters[0]?.id || "")}"
      aria-label="${escapeHtml(`${site.name}, ${n} ${noun}`)}"
    >
      <span class="astral-site-copy">${escapeHtml(site.name)}</span>
      ${count}
    </button>
  `;
}

// What the Export pop-up can make. Image needs a graph on screen.
const PROTO_EXPORT_WHAT = [
  { id: "chart", name: "Chart data", note: "What the graph shows now", mark: "export-chart" },
  { id: "source", name: "Source data", note: "Every reading, for the dates you choose", mark: "export-source" },
  { id: "image", name: "Image", note: "The graph as a PNG", mark: "export-image" },
  { id: "pdf", name: "PDF", note: "The chart data, to share or print", mark: "export-pdf" },
];

// People and Usage are tables, so they have no source data or image.
const PROTO_EXPORT_TABLE_WHAT = [
  { id: "chart", name: "Table data", note: "What the table shows now", mark: "export-table" },
  { id: "pdf", name: "PDF", note: "The table, to share or print", mark: "export-pdf" },
];

const PROTO_EXPORT_SOURCE_FORMATS = [
  { id: "csv", name: "CSV, comma", ext: "csv", sep: "," },
  { id: "csv-semicolon", name: "CSV, semicolon", ext: "csv", sep: ";" },
  { id: "csv-tab", name: "CSV, tab", ext: "csv", sep: "\t" },
  { id: "xlsx", name: "XLSX", ext: "xlsx" },
];

function protoExportIsTable(fileId) {
  return fileId === "users" || fileId === "usage";
}

function protoExportChoices(fileId) {
  if (protoExportIsTable(fileId)) return PROTO_EXPORT_TABLE_WHAT;
  return PROTO_EXPORT_WHAT.filter((item) => item.id !== "image" || protoPaneIsGraph());
}

// The last choice and options, kept for the session so a repeat export is the icon, then Export.
function protoExportPrefs() {
  const raw = store.prototypeExportPrefs && typeof store.prototypeExportPrefs === "object" ? store.prototypeExportPrefs : {};
  return {
    what: PROTO_EXPORT_WHAT.some((item) => item.id === raw.what) ? raw.what : "chart",
    format: PROTO_EXPORT_SOURCE_FORMATS.some((item) => item.id === raw.format) ? raw.format : "csv",
    quality: raw.quality === "actual" ? "actual" : "all",
    time: raw.time === "uk" ? "uk" : "utc",
    ids: raw.ids === true,
    // Source data dates work like the Reports date range. Exact dates start as the graph's dates.
    rangeMode: PROTO_REPORT_RANGE_MODES.some((item) => item.id === raw.rangeMode) ? raw.rangeMode : "dates",
    rangePreset: protoReportPick(PROTO_REPORT_RANGE_PRESETS, raw.rangePreset || "last-month"),
    rangeCount: raw.rangeCount == null ? "3" : String(raw.rangeCount).slice(0, 3),
    rangeUnit: protoReportRangeUnit(raw.rangeUnit).id,
    rangeCurrent: raw.rangeCurrent === true,
  };
}

function protoExportModalState() {
  const raw = store.prototypeExportModal;
  if (!raw || typeof raw !== "object" || !raw.file) return null;
  const file = String(raw.file);
  if (protoExportNoData(file)) return null;
  const prefs = protoExportPrefs();
  // Too large to graph opens on Source data. Chart data, Image and PDF are still built from the same data in the background.
  const limit = raw.limit === true && Boolean(protoGraphLimit(file));
  const what = protoExportChoices(file).some((item) => item.id === prefs.what) ? prefs.what : "chart";
  const errors = raw.errors && typeof raw.errors === "object" ? raw.errors : {};
  // Source data needs more fields, so they sit on a second step.
  const step = what === "source" && raw.step === 2 ? 2 : 1;
  const dir = raw.dir === "next" || raw.dir === "back" ? raw.dir : "";
  // Source data step 2 exists for the dates, so the From and To fields always show.
  return { file, what, prefs, step, dir, limit, more: raw.more === true, edit: what === "source", errors };
}

function protoExportSourceFormat(id) {
  return PROTO_EXPORT_SOURCE_FORMATS.find((item) => item.id === id) || PROTO_EXPORT_SOURCE_FORMATS[0];
}

// Meter points are always the ones on the graph now.
function protoExportMeters(fileId) {
  if (fileId === "all" && store.prototypeScope !== "group") {
    const site = protoSiteByMeter(store.activePrototypeMeter);
    return site ? protoSiteViewMeters(site) : [];
  }
  return protoIntervalCsvMeters(fileId) || [];
}

function protoExportGraphDates() {
  const span = protoDateSpan();
  return { from: span.from, to: span.to };
}

// A whole number of days, weeks or months, or null.
function protoExportRangeCount(prefs) {
  const n = Number(String(prefs.rangeCount ?? "").trim());
  return Number.isInteger(n) && n >= 1 && n <= PROTO_REPORT_RANGE_MAX ? n : null;
}

// Exact dates are typed. A common or custom range counts back from today.
function protoExportSourceDates(state) {
  if (!state?.edit) return protoExportGraphDates();
  const { prefs } = state;
  if (prefs.rangeMode === "dates") {
    return { from: protoFromUkDate(store.prototypeExportFrom), to: protoFromUkDate(store.prototypeExportTo) };
  }
  if (prefs.rangeMode === "rolling" && !protoExportRangeCount(prefs)) return { from: null, to: null };
  return protoReportRangeAt(prefs, protoToday());
}

// Each error names its field, says what is needed, and keeps what they typed.
function protoExportDateErrors(prefs = protoExportPrefs()) {
  const errors = {};
  if (prefs.rangeMode === "preset") return errors;
  if (prefs.rangeMode === "rolling") {
    if (!protoExportRangeCount(prefs)) {
      errors.count = `Enter how many ${protoReportRangeUnit(prefs.rangeUnit).many}, a whole number from 1 to ${PROTO_REPORT_RANGE_MAX}.`;
    }
    return errors;
  }
  const today = protoDayStamp(protoToday());
  const check = (key, label) => {
    const text = String(store[key === "from" ? "prototypeExportFrom" : "prototypeExportTo"] || "").trim();
    const day = protoFromUkDate(text);
    if (!text) errors[key] = `Enter a ${label} date.`;
    else if (!day) errors[key] = `Enter ${label} as dd/mm/yyyy.`;
    else if (protoDayStamp(day) > today) errors[key] = `${label} must be today or earlier.`;
    return day;
  };
  const from = check("from", "Data from");
  const to = check("to", "Data to");
  if (!errors.from && !errors.to && protoDayStamp(to) < protoDayStamp(from)) {
    errors.to = "Data to must be the same as or after Data from.";
  }
  return errors;
}

function protoExportPlural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

const PROTO_EXPORT_SUM_FORMAT = {
  csv: "CSV with commas",
  "csv-semicolon": "CSV with semicolons",
  "csv-tab": "CSV with tabs",
  xlsx: "XLSX",
};

// One sentence, for example "Exports 3 meter points for 29 Sep to 6 Oct 2026 as CSV with commas, actual readings only."
// A sentence avoids clashing separators, because format names such as "CSV, comma" hold a comma. Defaults stay out.
function protoExportSummary(state) {
  const { file, what, prefs } = state;
  let text = "Exports ";
  if (file === "users") text += protoExportPlural(protoUserPeople().length, "person", "people");
  else if (file === "usage") text += protoExportPlural(protoUsagePack().rows.length, "row", "rows");
  else {
    text += protoExportPlural(protoExportMeters(file).length, "meter point", "meter points");
    const dates = what === "source" ? protoExportSourceDates(state) : protoExportGraphDates();
    if (dates.from && dates.to && protoDayStamp(dates.from) <= protoDayStamp(dates.to)) {
      text += ` for ${protoRangeWords(dates.from, dates.to)}`;
    }
  }
  if (what === "source") {
    text += ` as ${PROTO_EXPORT_SUM_FORMAT[protoExportSourceFormat(prefs.format).id]}`;
    const extras = [];
    if (prefs.quality === "actual") extras.push("actual readings only");
    if (prefs.time === "uk") extras.push("in UK time");
    if (prefs.ids) extras.push("with source IDs");
    if (extras.length) text += `, ${extras.join(", ")}`;
  } else {
    text += ` as ${what === "pdf" ? "PDF" : what === "image" ? "PNG" : PROTO_EXPORT_SUM_FORMAT.csv}`;
  }
  return `${text}.`;
}

// The only greyed-out Export. Every meter point in view has stopped sending readings before the dates picked, so the graph is empty too.
function protoExportNoData(fileId) {
  return protoNoReadings(protoExportMeters(String(fileId || "")));
}

// The graph draws up to this many meter point days. 125 meter points for 8 days, or 31 for a month.
const PROTO_GRAPH_MAX = 1000;

function protoGraphDays() {
  const { from, to } = protoDateSpan();
  return Math.round((protoDayStamp(to) - protoDayStamp(from)) / 86400000) + 1;
}

// Null while the graph can show the selection. Mixed units ask for a unit first, so they never reach the limit.
// It counts the same meter points the export would, so the message and the export agree.
function protoGraphLimit(fileId) {
  if (!protoPaneIsGraph() && protoPaneId() !== "demand") return null;
  const id = String(fileId || "");
  const meters = protoExportMeters(id);
  if (!meters.length || protoConsumptionUnitsMixed(meters)) return null;
  const days = protoGraphDays();
  if (meters.length * days <= PROTO_GRAPH_MAX) return null;
  const scope = id === "compare" ? protoCompareLevel() : id.startsWith("group:") ? "group" : "site";
  return { file: id, meters: meters.length, days, scope };
}

// In the graph area, in place of the graph and its breakdowns. The date and Compare controls stay above it.
function protoGraphLimitHtml(limit) {
  const fewer =
    limit.scope === "site" ? "" : limit.scope === "meter" ? "fewer meter points or " : "fewer sites or ";
  const act = protoCanAct();
  const narrow = `To see a graph, choose ${fewer}a shorter date range.`;
  const body = act ? `${narrow} To get every reading, export the data.` : narrow;
  return protoChartWrap(
    `
      <div class="astral-chart-mix astral-graph-limit" role="status">
        <h3>Too much data to show on the graph</h3>
        <p>${escapeHtml(body)}</p>
        ${
          act
            ? `<div class="astral-actions">${protoBtn(
                `${protoIconMark("export")}<span>Export data</span>`,
                `data-proto-graph-export="${escapeHtml(limit.file)}" aria-haspopup="dialog"`,
                { html: true }
              )}</div>`
            : ""
        }
      </div>
    `,
    protoPaneChartLabel(false),
    false,
    true
  );
}

// Export opens one pop-up that holds every export option.
function protoExportControl(fileId) {
  if (!protoCanAct()) return "";
  const open = protoExportModalState()?.file === String(fileId || "");
  if (protoExportNoData(fileId)) {
    return `
      <div class="astral-export">
        ${protoIconBtn("export", "Export, no data in these dates", 'data-proto-export="toggle" aria-disabled="true"', {
          tipLabel: "There is no data to export in these dates. Choose a different date range.",
        })}
      </div>
    `;
  }
  return `
    <div class="astral-export">
      ${protoIconBtn(
        "export",
        "Export",
        `data-proto-export="toggle" data-proto-file="${escapeHtml(fileId)}" aria-haspopup="dialog"`,
        { on: open }
      )}
    </div>
  `;
}

function protoExportRadio(attr, on, label) {
  return `<button type="button" role="radio" class="astral-meter-src-item" aria-checked="${on ? "true" : "false"}" tabindex="${
    on ? "0" : "-1"
  }" ${attr}>${protoRadio(on)}<span>${escapeHtml(label)}</span></button>`;
}

function protoExportRadioSet(key, legend, list, value) {
  const id = `astral-export-${key}-label`;
  return `
    <fieldset class="astral-report-split">
      <legend id="${id}">${escapeHtml(legend)}</legend>
      <div class="astral-meter-src" role="radiogroup" aria-labelledby="${id}">
        ${list
          .map((item) =>
            protoExportRadio(`data-proto-export-opt="${escapeHtml(`${key}:${item.id}`)}"`, item.id === value, item.name)
          )
          .join("")}
      </div>
    </fieldset>
  `;
}

function protoExportDatesHtml(state) {
  if (protoExportIsTable(state.file)) return "";
  if (state.what === "source") {
    const { prefs, errors } = state;
    const countError = errors.count ? 'aria-invalid="true" aria-describedby="astral-export-range-count-error"' : "";
    return `
      ${protoRangeFieldsHtml(prefs, {
        key: "export",
        ref: protoToday(),
        from: "exportFrom",
        to: "exportTo",
        errors,
        count: protoField(
          "Last",
          `type="text" name="proto-export-range-count" value="${escapeHtml(prefs.rangeCount)}" inputmode="numeric" placeholder="3" maxlength="3" autocomplete="off" ${countError}`
        ),
      })}
    `;
  }
  const { from, to } = protoExportGraphDates();
  return `<div><dt>Dates</dt><dd>${escapeHtml(protoRangeWords(from, to))}</dd></div>`;
}

function protoExportFieldsHtml(state) {
  const { what, prefs } = state;
  const dates = protoExportDatesHtml(state);
  const fixed = what === "pdf" ? "PDF" : what === "image" ? "PNG" : "CSV, comma";
  const facts = [dates, `<div><dt>Format</dt><dd>${escapeHtml(fixed)}</dd></div>`].filter(Boolean).join("");
  if (what !== "source") return `<dl class="astral-export-facts">${facts}</dl>`;
  return `
    ${dates}
    ${protoReportOptionSelect("export-format", "Format", PROTO_EXPORT_SOURCE_FORMATS, prefs.format)}
    ${protoAccordion({
      id: "astral-export-more",
      open: state.more,
      name: "More options",
      attr: "data-proto-export-more",
      modifier: "astral-export-more",
      inner: `
        ${protoExportRadioSet("quality", "Data quality", PROTO_REPORT_QUALITY, prefs.quality)}
        ${protoExportRadioSet("time", "Time zone", PROTO_REPORT_TIME, prefs.time)}
        <button
          type="button"
          role="checkbox"
          class="astral-report-consent"
          aria-checked="${prefs.ids ? "true" : "false"}"
          data-proto-export-ids
        >
          ${protoCheck(prefs.ids)}
          <span class="astral-report-consent-copy">
            <span>Include source IDs</span>
            <span class="astral-muted">Adds the meter point ID and the cumulative data stream, where there is one.</span>
          </span>
        </button>
      `,
    })}
  `;
}

function protoExportModal() {
  const state = protoExportModalState();
  if (!state || !protoCanAct()) return "";
  const choices = protoExportChoices(state.file);
  const sourceStep = state.what === "source" && state.step === 2;
  const sourcePick = state.what === "source" && state.step === 1;
  const body = sourceStep
    ? protoExportFieldsHtml(state)
    : `
          <fieldset class="astral-report-split">
            <legend id="astral-export-what-label">What do you want to export?</legend>
            <div
              class="astral-report-types is-pair"
              role="radiogroup"
              aria-labelledby="astral-export-what-label"
              ${state.errors.what ? 'aria-describedby="astral-export-what-error"' : ""}
            >
              ${choices
                .map((item) => {
                  const on = state.what === item.id;
                  const note = !state.limit
                    ? item.note
                    : item.id === "chart"
                      ? "Totals for your selection"
                      : item.id === "image"
                        ? "A chart of the totals, as a PNG"
                        : item.note;
                  return `
                    <button
                      type="button"
                      role="radio"
                      class="astral-report-type${on ? " is-on" : ""}"
                      aria-checked="${on ? "true" : "false"}"
                      tabindex="${on ? "0" : "-1"}"
                      data-proto-export-kind="${escapeHtml(item.id)}"
                    >
                      <span class="astral-report-type-head">${protoRadio(on)}${protoTypeBadge(item.mark)}<span>${escapeHtml(item.name)}</span></span>
                      <span class="astral-muted">${escapeHtml(note)}</span>
                    </button>
                  `;
                })
                .join("")}
            </div>
            ${state.errors.what ? `<p class="astral-export-error" id="astral-export-what-error" role="alert">${escapeHtml(state.errors.what)}</p>` : ""}
          </fieldset>
          ${sourcePick ? "" : protoExportFieldsHtml(state)}
        `;
  const motion = state.dir ? ` is-step-${state.dir}` : "";
  return `
    <div class="astral-modal-back" data-proto-modal="export">
      <div
        class="astral-modal astral-report-pick astral-export-pick has-menus${motion}"
        id="astral-export-pick"
        role="dialog"
        aria-modal="true"
        aria-labelledby="astral-export-pick-title"
      >
        ${
          sourceStep
            ? protoModalHead("astral-export-pick-title", "Export source data", "", "export", 'data-proto-export-step="back"')
            : protoModalHead("astral-export-pick-title", "Export", "", "export")
        }
        <div class="astral-modal-body">
          ${body}
        </div>
        <div class="astral-modal-foot">
          ${sourcePick ? "" : `<p class="astral-export-sum" aria-live="polite">${escapeHtml(protoExportSummary(state))}</p>`}
          <div class="astral-actions">
            ${sourcePick ? protoBtn("Continue", 'data-proto-export-step="next"') : protoBtn("Export", 'data-proto-export="go"')}
            ${protoGhost("Cancel", 'data-proto-modal-close="export"')}
          </div>
        </div>
      </div>
    </div>
  `;
}

// Moves between the export steps. The slide plays once, then later renders stay still.
function protoExportStep(step) {
  const raw = store.prototypeExportModal;
  if (!raw || !protoExportModalState()) return;
  setProto({ prototypeExportModal: { ...raw, step, dir: step === 2 ? "next" : "back", errors: {} } });
  store.prototypeExportModal = { ...store.prototypeExportModal, dir: "" };
  if (step === 2) protoRestoreFocus('#astral-fs #astral-export-pick [data-proto-export-step="back"]');
  else protoRestoreFocus("#astral-fs #astral-export-pick .astral-report-type.is-on");
}

// True while an arrow key moves a radio pick, so a pick that opens the next step waits for a click, Enter or Space.
let protoRadioByArrow = false;

function protoSetExportPrefs(patch) {
  setProto({ prototypeExportPrefs: { ...protoExportPrefs(), ...patch } });
}

function protoOpenExport(fileId, from = "") {
  const graph = protoExportGraphDates();
  const limit = Boolean(protoGraphLimit(fileId));
  setProto({
    prototypeExportModal: { file: String(fileId || ""), ...(limit ? { limit: true, from } : {}) },
    // The full data starts as exactly what they asked the graph for, on Source data.
    ...(limit ? { prototypeExportPrefs: { ...protoExportPrefs(), what: "source", rangeMode: "dates" } } : {}),
    prototypeExportFrom: protoFormatUkDate(graph.from),
    prototypeExportTo: protoFormatUkDate(graph.to),
    prototypeExportOpen: false,
    prototypeDateOpen: false,
    prototypeTreeFilterOpen: false,
    prototypePaneFilterOpen: false,
    prototypeUserRoleFilterOpen: false,
    prototypeSelectOpen: "",
    prototypeAckOpen: "",
  });
  protoRestoreFocus("#astral-fs #astral-export-pick .astral-report-type.is-on");

}

// Focus goes back to whichever button opened the pop-up.
function protoExportBackSelector(file) {
  const id = CSS.escape(String(file || ""));
  return store.prototypeExportModal?.from === "graph"
    ? `#astral-fs [data-proto-graph-export="${id}"]`
    : `#astral-fs [data-proto-export="toggle"][data-proto-file="${id}"]`;
}

// Validates Source data dates, queues the file, closes the pop-up and sends focus back to the Export icon.
async function protoExportGo() {
  const state = protoExportModalState();
  if (!state) return;
  const { file, what, prefs } = state;
  if (what === "source" && state.step !== 2) {
    protoExportStep(2);
    return;
  }
  if (what === "source" && state.edit) {
    const errors = protoExportDateErrors();
    if (Object.keys(errors).length) {
      setProto({ prototypeExportModal: { ...store.prototypeExportModal, errors } });
      if (errors.count) protoRestoreFocus('#astral-fs input[name="proto-export-range-count"]');
      else protoFocusDayCalInput(`#astral-fs input[name="proto-export-${errors.from ? "from" : "to"}"]`);
      return;
    }
  }
  const back = protoExportBackSelector(file);
  if (what === "pdf" || what === "chart") {
    protoQueueExport(what === "pdf" ? "pdf" : "csv", file);
  } else if (what === "image") {
    // Too large to graph has nothing on screen to capture, so the image is drawn from the data instead.
    const shot = state.limit ? protoPackImageShot(file) : await protoChartImageShot();
    if (!shot) {
      setProto({ prototypeExportModal: { ...store.prototypeExportModal, errors: { what: "The graph is still loading. Try again when it shows." } } });
      protoRestoreFocus("#astral-fs #astral-export-pick .astral-report-type.is-on");
      return;
    }
    const id = protoNewDownloadId();
    protoExportImageKeep(id, shot);
    protoQueueExport("png", file, { id, spec: { what: "image" } });
  } else {
    const { from, to } = protoExportSourceDates(state);
    const format = protoExportSourceFormat(prefs.format);
    const name = `${protoExportSourceName(file)} source data ${protoIso(from)} to ${protoIso(to)}`;
    protoQueueExport(format.ext === "xlsx" ? "xlsx" : "csv", file, {
      name,
      spec: {
        what: "source",
        from: protoIso(from),
        to: protoIso(to),
        format: format.id,
        quality: prefs.quality,
        time: prefs.time,
        ids: prefs.ids,
        meters: protoExportMeters(file).map((meter) => meter.id),
      },
    });
  }
  protoRestoreFocus(back);
}

function protoKnownPane(raw) {
  if (
    raw === "alerts" ||
    raw === "profile" ||
    raw === "queries" ||
    raw === "cost" ||
    raw === "carbon" ||
    raw === "power" ||
    raw === "demand" ||
    raw === "weather"
  ) {
    return raw;
  }
  return "consumption";
}

function protoPaneId() {
  return protoKnownPane(store.prototypePane);
}

function protoPaneIsGraph() {
  return protoPaneIdIsGraph(protoPaneId());
}

function protoPaneIdIsGraph(pane) {
  return pane === "consumption" || pane === "cost" || pane === "carbon";
}

// Consumption, Cost, and Carbon are one graph seen three ways, so moving between them morphs.
function protoPaneScene(pane) {
  return protoPaneIdIsGraph(pane) ? "graph" : String(pane || "");
}

function protoPaneChartLabel(dual) {
  const pane = protoPaneId();
  if (pane === "cost") return "Cost";
  if (pane === "carbon") return "Carbon";
  if (pane === "demand") return "Demand";
  return dual ? "Incoming and outgoing" : "Consumption";
}

function protoChartIsGraph(label) {
  return (
    label === "Consumption" ||
    label === "Incoming and outgoing" ||
    label === "Cost" ||
    label === "Carbon" ||
    label === "Demand"
  );
}

function protoMeasureUnit(meters) {
  const pane = protoPaneId();
  if (pane === "cost") return "£";
  if (pane === "carbon") return "kgCO2e";
  return protoMetersUseUnit(meters);
}

function protoMeasurePlaces() {
  return 1;
}

function protoMeasureFactor(meters) {
  const pane = protoPaneId();
  const list = meters || [];
  if (pane === "cost") {
    const billed = list.filter((item) => item.direction !== "Export");
    const use = billed.length ? billed : list;
    if (!use.length) return 0.18;
    return use.reduce((n, item) => n + protoMeterRatePence(item), 0) / use.length / 100;
  }
  if (pane === "carbon") {
    if (!list.length) return 0.2;
    return list.reduce((n, item) => n + protoMeterCarbonKg(item), 0) / list.length;
  }
  return 1;
}

function protoScaleValue(value, factor, places) {
  if (value == null) return null;
  return Number((Number(value) * factor).toFixed(places));
}

function protoScalePoints(points, meters) {
  const list = points || [];
  if (!protoPaneIsGraph()) return protoFilterProfilePoints(list, meters);
  if (protoPaneId() === "consumption") {
    const unit = protoMeasureUnit(meters);
    return protoFilterProfilePoints(
      list.map((point) => ({ ...point, unit: point.unit || unit })),
      meters
    );
  }
  const factor = protoMeasureFactor(meters);
  const places = protoMeasurePlaces(meters);
  const unit = protoMeasureUnit(meters);
  return protoFilterProfilePoints(
    list.map((point) => ({
      ...point,
      value: protoScaleValue(point.value, factor, places),
      last: point.last == null ? point.last : protoScaleValue(point.last, factor, places),
      unit,
    })),
    meters
  );
}

function protoScaleTracks(tracks, meters) {
  return (tracks || []).map((track) => ({
    ...track,
    points: protoScalePoints(track.points, track.meter ? [track.meter] : track.meters?.length ? track.meters : meters),
  }));
}

function protoPaneShell(headHtml, bodyHtml) {
  return `
    <div class="astral-detail">
      <div class="astral-pane-head">${headHtml}</div>
      <div class="astral-pane-body">
        ${bodyHtml}
      </div>
    </div>
  `;
}

function protoPaneTabs(alertCount, queryCount) {
  const active = protoPaneId();
  const alertsName = alertCount ? `Alerts · ${alertCount}` : "Alerts";
  const queriesName = queryCount ? `Queries · ${queryCount}` : "Queries";
  const items = [
    { id: "consumption", name: "Consumption" },
    { id: "cost", name: "Cost" },
    { id: "carbon", name: "Carbon" },
    { id: "demand", name: "Demand" },
    { id: "power", name: "Power factor" },
    { id: "weather", name: "Weather" },
    { id: "profile", name: "Site profile" },
    { id: "alerts", name: alertsName },
    { id: "queries", name: queriesName },
  ];
  return protoTabs(
    items,
    active,
    "data-proto-pane",
    "Consumption, Cost, Carbon, Demand, Power factor, Weather, Site profile, Alerts, and Queries"
  );
}

const PROTO_WEATHER_MEASURES = [
  { id: "temperature", name: "Temperature", note: "Average temperature in °C" },
  { id: "degree", name: "Degree days", note: "Heating and cooling degree days" },
  { id: "rain", name: "Rainfall", note: "Total rainfall in mm" },
];

const PROTO_DEGREE_BASE = 15.5;

// Met Office stations the prototype reads from. Each site uses the nearest one.
const PROTO_WEATHER_STATIONS = [
  { name: "Heathrow", at: [51.479, -0.449] },
  { name: "Manchester Airport", at: [53.354, -2.275] },
  { name: "Edinburgh Gogarbank", at: [55.928, -3.343] },
  { name: "Bishopton", at: [55.907, -4.531] },
  { name: "Aberdeen Dyce", at: [57.206, -2.202] },
  { name: "Aviemore", at: [57.206, -3.827] },
  { name: "Leuchars", at: [56.377, -2.861] },
  { name: "Eskdalemuir", at: [55.312, -3.206] },
  { name: "Newcastle Albemarle", at: [55.02, -1.88] },
  { name: "Leeming", at: [54.296, -1.533] },
  { name: "Sheffield", at: [53.381, -1.49] },
  { name: "Crosby", at: [53.497, -3.056] },
  { name: "Watnall", at: [53.005, -1.251] },
  { name: "Coleshill", at: [52.48, -1.689] },
  { name: "Cambridge NIAB", at: [52.245, 0.102] },
  { name: "Oxford", at: [51.761, -1.262] },
  { name: "Bristol Airport", at: [51.382, -2.719] },
  { name: "Cardiff Bute Park", at: [51.488, -3.187] },
  { name: "Hurn", at: [50.779, -1.835] },
  { name: "Herstmonceux", at: [50.89, 0.318] },
  { name: "Exeter Airport", at: [50.737, -3.405] },
  { name: "Mount Batten", at: [50.355, -4.121] },
];

function protoWeatherMeasure() {
  const id = String(store.prototypeWeatherMeasure || "");
  return PROTO_WEATHER_MEASURES.some((item) => item.id === id) ? id : "temperature";
}

// The measure the user was on before Degree days, so Back returns there.
function protoWeatherMeasureBack() {
  const id = String(store.prototypeWeatherMeasureBack || "");
  return id !== "degree" && PROTO_WEATHER_MEASURES.some((item) => item.id === id) ? id : "temperature";
}

function protoKmBetween(a, b) {
  const rad = (d) => (d * Math.PI) / 180;
  const dLat = rad(b[0] - a[0]);
  const dLon = rad(b[1] - a[1]);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a[0])) * Math.cos(rad(b[0])) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
}

function protoWeatherStation(site) {
  const at = PROTO_SITE_GEO[site?.name] || PROTO_WEATHER_STATIONS[0].at;
  const near = PROTO_WEATHER_STATIONS.map((station) => ({ ...station, km: protoKmBetween(at, station.at) })).sort(
    (a, b) => a.km - b.km
  )[0];
  return { ...near, km: Math.max(1, Math.round(near.km)) };
}

function protoWeatherRand(seed) {
  let h = 2166136261;
  const text = String(seed);
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 100000) / 100000;
}

// A plain seasonal model: cooler and wetter to the north and west, warmest in late July.
function protoWeatherDay(station, day) {
  const [lat, lon] = station.at;
  const start = new Date(day.getFullYear(), 0, 1);
  const doy = Math.round((day - start) / 86400000);
  const key = `${station.name}|${protoIso(day)}`;
  const base = 10.6 - (lat - 51) * 0.42;
  const swing = 6.4 - Math.max(0, -lon - 3) * 0.6;
  const noise = (protoWeatherRand(`${key}|t`) - 0.5) * 5;
  // The bar graph starts at zero, so a day's average stays just above freezing.
  const temp = Math.max(0.5, base + swing * Math.cos((2 * Math.PI * (doy - 201)) / 365) + noise);
  const wet = 0.42 + Math.max(0, -lon - 1) * 0.04 + (lat - 51) * 0.015;
  const rains = protoWeatherRand(`${key}|r`) < wet;
  const rain = rains ? -Math.log(1 - protoWeatherRand(`${key}|a`) * 0.97) * (3.1 + Math.max(0, -lon - 2) * 0.7) : 0;
  return {
    temp,
    heat: Math.max(0, PROTO_DEGREE_BASE - temp),
    cool: Math.max(0, temp - PROTO_DEGREE_BASE),
    rain,
  };
}

function protoRound(value, places = 1) {
  const f = 10 ** places;
  return Math.round(value * f) / f;
}

// One bucket per step of the date control: hours for a day, days for up to 62 days, months beyond.
function protoWeatherRows(station) {
  const span = protoDateSpan();
  if (span.kind === "interval") {
    const day = protoWeatherDay(station, span.from);
    const wetHours = Array.from({ length: 24 }, (_, h) => protoWeatherRand(`${station.name}|${protoIso(span.from)}|${h}`));
    const wetSum = wetHours.filter((n) => n > 0.6).reduce((n, v) => n + v, 0) || 1;
    return wetHours.map((n, h) => ({
      label: `${String(h).padStart(2, "0")}.00`,
      name: `${String(h).padStart(2, "0")}.00 ${protoChartZone()}`,
      temp: protoRound(Math.max(0.5, day.temp + 3.6 * Math.cos((2 * Math.PI * (h - 15)) / 24))),
      rain: protoRound(n > 0.6 ? (day.rain * n) / wetSum : 0),
      heat: null,
      cool: null,
    }));
  }
  const days = Math.round((span.to - span.from) / 86400000) + 1;
  const list = Array.from({ length: days }, (_, i) => {
    const date = protoAddDays(span.from, i);
    return { date, ...protoWeatherDay(station, date) };
  });
  if (span.kind === "day") {
    return list.map((row) => ({
      label: protoFormatDay(row.date),
      name: protoFormatFullDay(row.date),
      temp: protoRound(row.temp),
      rain: protoRound(row.rain),
      heat: protoRound(row.heat),
      cool: protoRound(row.cool),
    }));
  }
  const months = new Map();
  list.forEach((row) => {
    const key = `${row.date.getFullYear()}-${row.date.getMonth()}`;
    if (!months.has(key)) months.set(key, { date: row.date, rows: [] });
    months.get(key).rows.push(row);
  });
  return [...months.values()].map(({ date, rows }) => {
    const sum = (key) => rows.reduce((n, row) => n + row[key], 0);
    const yy = String(date.getFullYear()).slice(2);
    return {
      label: `${PROTO_MONTHS[date.getMonth()]} ${yy}`,
      name: `${PROTO_MONTHS_LONG[date.getMonth()]} ${date.getFullYear()}`,
      temp: protoRound(sum("temp") / rows.length),
      rain: protoRound(sum("rain")),
      heat: protoRound(sum("heat")),
      cool: protoRound(sum("cool")),
    };
  });
}

const PROTO_WEATHER_GRAIN = {
  interval: { adj: "hourly", one: "hour", many: "hours" },
  day: { adj: "daily", one: "day", many: "days" },
  month: { adj: "monthly", one: "month", many: "months" },
};

function protoWeatherAmount(value, unit) {
  const n = Number(value) || 0;
  const text = n.toLocaleString("en-GB", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  return unit === "°C" ? `${text} °C` : `${text} ${unit}`;
}

// Lowest, highest and average for one measure, with when each fell. Totals only where adding up makes sense.
function protoWeatherFigures(rows, key, { noun, unit, total }) {
  const grain = PROTO_WEATHER_GRAIN[protoDateSpan().kind] || PROTO_WEATHER_GRAIN.day;
  const have = rows.filter((row) => row[key] != null);
  if (!have.length) return [];
  const sum = have.reduce((n, row) => n + row[key], 0);
  const high = have.reduce((best, row) => (row[key] > best[key] ? row : best));
  const low = have.reduce((best, row) => (row[key] < best[key] ? row : best));
  const across = `Across ${have.length} ${have.length === 1 ? grain.one : grain.many}`;
  const at = (row) => (grain.one === "hour" ? `At ${row.name}` : grain.one === "day" ? `On ${row.name}` : `In ${row.name}`);
  return [
    ...(total ? [{ name: `Total ${noun}`, value: protoWeatherAmount(sum, unit), note: across }] : []),
    { name: `Highest ${grain.adj} ${noun}`, value: protoWeatherAmount(high[key], unit), note: at(high) },
    { name: `Lowest ${grain.adj} ${noun}`, value: protoWeatherAmount(low[key], unit), note: at(low) },
    {
      name: `Average ${grain.adj} ${noun}`,
      value: protoWeatherAmount(sum / have.length, unit),
      note: total ? `Total divided by ${have.length} ${have.length === 1 ? grain.one : grain.many}` : across,
    },
  ];
}

function protoWeatherFigureGroup(name, figures) {
  if (!figures.length) return "";
  return `
    <section class="astral-figures-group"${name ? ` aria-label="${escapeHtml(name)}"` : ""}>
      ${name ? `<h4 class="astral-figures-head">${escapeHtml(name)}</h4>` : ""}
      <dl class="astral-figures">
        ${figures
          .map(
            (item) => `
          <div class="astral-figure">
            <dt>${escapeHtml(item.name)}</dt>
            <dd class="astral-figure-value">${escapeHtml(item.value)}</dd>
            <dd class="astral-figure-note">${escapeHtml(item.note)}</dd>
          </div>`
          )
          .join("")}
      </dl>
    </section>
  `;
}

// The measure is picked from the graph header, where other graphs keep Chart settings.
function protoWeatherMeasureSelect(measure) {
  const name = PROTO_WEATHER_MEASURES.find((item) => item.id === measure)?.name || "Temperature";
  return protoSelect({
    id: "weather-measure",
    label: `Measure, ${name}`,
    value: measure,
    options: PROTO_WEATHER_MEASURES.map((item) => ({
      value: item.id,
      label: item.name,
      note: item.note,
    })),
  });
}

function protoWeatherChart(rows, measure) {
  const unit = measure === "temperature" ? "°C" : measure === "rain" ? "mm" : "°C days";
  const title =
    measure === "temperature" ? "Average temperature" : measure === "rain" ? "Rainfall" : "Heating and cooling degree days";
  const points = rows.map((row) => {
    const base = { label: row.label, quality: "actual", unit };
    if (measure === "degree") {
      return {
        ...base,
        value: row.heat,
        last: row.cool,
        lastQuality: "actual",
        nowLabel: "Heating degree days",
        lastLabel: "Cooling degree days",
        spoken: `${row.name}. Heating degree days ${protoWeatherAmount(row.heat, unit)}. Cooling degree days ${protoWeatherAmount(row.cool, unit)}.`,
      };
    }
    const value = measure === "rain" ? row.rain : row.temp;
    return { ...base, value, spoken: `${row.name}. ${protoWeatherAmount(value, unit)}.` };
  });
  const dual = measure === "degree";
  return protoWithStore(
    {
      prototypePane: "consumption",
      prototypePaneFilters: [],
      prototypeChartSliceOff: [],
      prototypeChartFlows: ["in", "out"],
      prototypeChartPoint: null,
    },
    () =>
      protoBarChart(points, `Weather, ${title}`, {
        dual,
        still: true,
        ...(dual ? { keyNames: { in: "Heating degree days", out: "Cooling degree days" } } : {}),
        heading: { title, when: `${protoChartWhen()} ${protoChartZone()}`, tools: protoWeatherMeasureSelect(measure) },
      })
  );
}

// Several sites read the average of their nearest stations, each station counted once.
function protoWeatherRowsFor(sites) {
  const seen = new Map();
  (sites || []).filter(Boolean).forEach((site) => {
    const station = protoWeatherStation(site);
    if (!seen.has(station.name)) seen.set(station.name, station);
  });
  const stations = [...seen.values()];
  if (!stations.length) return [];
  const all = stations.map((station) => protoWeatherRows(station));
  if (all.length === 1) return all[0];
  const mean = (key, i) => {
    const vals = all.map((rows) => rows[i]?.[key]).filter((v) => v != null);
    return vals.length ? protoRound(vals.reduce((a, b) => a + b, 0) / vals.length) : null;
  };
  return all[0].map((row, i) => ({
    ...row,
    temp: mean("temp", i),
    rain: mean("rain", i),
    heat: mean("heat", i),
    cool: mean("cool", i),
  }));
}

// One measure at a time: its graph, then its figures. Units are always said.
function protoWeatherPane(sites) {
  const measure = protoWeatherMeasure();
  const kind = protoDateSpan().kind;
  const rows = protoWeatherRowsFor(Array.isArray(sites) ? sites : [sites]);
  if (measure === "degree" && kind === "interval") {
    const span = protoDateSpan();
    const custom = protoDatePreset() === "custom";
    const end = `${span.to.getDate()} ${PROTO_MONTHS_LONG[span.to.getMonth()]}`;
    const back = PROTO_WEATHER_MEASURES.find((item) => item.id === protoWeatherMeasureBack());
    const view = custom ? `View 7 days to ${end}` : "View last 7 days";
    return protoChartWrap(
      `
        <div class="astral-chart-mix astral-graph-limit" role="status">
          <h3>Degree days need whole days</h3>
          <p>Degree days are counted once a day, so there is nothing to show for ${
            custom ? "1 day" : "24 hours"
          }. View 7 days, or go back to ${escapeHtml(back.name.toLowerCase())}.</p>
          <div class="astral-actions">
            ${protoBtn(view, `data-proto-weather-days="7"`)}
            ${protoGhost(`Back to ${back.name.toLowerCase()}`, `data-proto-weather-back="${escapeHtml(back.id)}"`)}
          </div>
        </div>
      `,
      "Weather, Heating and cooling degree days",
      false,
      true,
      {
        heading: {
          title: "Heating and cooling degree days",
          when: `${protoChartWhen()} ${protoChartZone()}`,
          tools: protoWeatherMeasureSelect(measure),
        },
      }
    );
  }
  const groups =
    measure === "degree"
      ? [
          protoWeatherFigureGroup(
            "Heating degree days",
            protoWeatherFigures(rows, "heat", { noun: "heating degree days", unit: "°C days", total: true })
          ),
          protoWeatherFigureGroup(
            "Cooling degree days",
            protoWeatherFigures(rows, "cool", { noun: "cooling degree days", unit: "°C days", total: true })
          ),
        ]
      : measure === "rain"
        ? [protoWeatherFigureGroup("", protoWeatherFigures(rows, "rain", { noun: "rainfall", unit: "mm", total: true }))]
        : [protoWeatherFigureGroup("", protoWeatherFigures(rows, "temp", { noun: "temperature", unit: "°C", total: false }))];
  const span = protoDateSpan();
  const spec = PROTO_BREAKDOWN_FOLDS.summary;
  const summary = protoAccordion({
    id: spec.id,
    open: Boolean(store[spec.field]),
    name: "Summary",
    note: protoRangeWords(span.from, span.to),
    attr: 'data-proto-breakdown="summary"',
    modifier: "astral-breakdown",
    clipClass: "astral-breakdown-clip",
    inner: `<div class="astral-pane-summary">${groups.join("")}</div>`,
  });
  return `
    ${protoWeatherChart(rows, measure)}
    ${summary}
  `;
}

const PROTO_PF_TARGET = 0.95;

const PROTO_PF_GRAIN = {
  interval: { adj: "half-hourly", one: "half hour", many: "half hours" },
  day: { adj: "daily", one: "day", many: "days" },
  month: { adj: "monthly", one: "month", many: "months" },
};

// A day's half-hour shape, rescaled to its total. The 8 largest meters set the shape, so a big group stays quick.
function protoShapeMeters(list) {
  if (list.length <= 8) return list;
  return [...list].sort((a, b) => protoDayKwh(b) - protoDayKwh(a)).slice(0, 8);
}

// Power factor is measured on the supply, so it reads incoming electricity meters only.
function protoPowerMeters(meters) {
  return (meters || []).filter((meter) => meter.direction !== "Export" && protoMeterKind(meter) === "electricity");
}

const PROTO_POWER_MEASURES = [
  { id: "pf", name: "Power factor", note: "How much of the power drawn does useful work" },
  { id: "reactive", name: "Reactive energy", note: "Lagging and leading kVArh, kept apart" },
  { id: "apparent", name: "Apparent energy", note: "kVAh, which sets the current the supply carries" },
];

// Network charges usually allow reactive energy up to about 33% of kWh in each half-hour, which is a power factor of 0.95.
const PROTO_PF_ALLOWANCE = Math.sqrt(1 / (PROTO_PF_TARGET * PROTO_PF_TARGET) - 1);
// Below a tenth of a usual half-hour, power factor falls towards 0 and says little, so it is left out.
const PROTO_PF_LOW_SHARE = 0.1;
const PROTO_PF_LOW_NOTE = "Use was too low for power factor to mean much, so it is not shown.";
const PROTO_PF_LEAD_NOTE = "Leading. Current ran ahead of voltage, often a sign of too much correction.";

function protoPowerMeasure() {
  const id = String(store.prototypePowerMeasure || "");
  return PROTO_POWER_MEASURES.some((item) => item.id === id) ? id : "pf";
}

function protoPowerMeasureSelect(measure) {
  const name = PROTO_POWER_MEASURES.find((item) => item.id === measure)?.name || "Power factor";
  return protoSelect({
    id: "power-measure",
    label: `Measure, ${name}`,
    value: measure,
    options: PROTO_POWER_MEASURES.map((item) => ({ value: item.id, label: item.name, note: item.note })),
  });
}

// The meters in view share one model. A site with correction equipment runs near 0.95 or above, and can turn leading at light load.
function protoPowerModel(list) {
  const seed = String(Math.round(protoWeatherRand(list.map((meter) => meter.id).join("|")) * 1e9));
  const corrected = protoWeatherRand(`${seed}|cap`) < 0.45;
  const lean = protoWeatherRand(`${seed}|pf`);
  return {
    seed,
    corrected,
    base: corrected ? 0.955 + lean * 0.035 : 0.84 + lean * 0.12,
    typical: list.reduce((n, meter) => n + protoDayKwh(meter), 0) / 48,
  };
}

// One half-hour on the meter: kWh, then lagging or leading kVArh, never both.
function protoPowerSlot(model, kwh, key) {
  const light = model.typical ? Math.max(0, Math.min(1, 1 - kwh / model.typical)) : 0;
  const noise = (protoWeatherRand(`${model.seed}|${key}`) - 0.5) * 0.03;
  const leading = model.corrected && light > 0.5;
  const pf = leading
    ? Math.max(0.8, model.base - 0.32 * (light - 0.5) + noise)
    : Math.min(0.995, Math.max(0.6, model.base - 0.08 * light + noise));
  const q = kwh * Math.tan(Math.acos(pf));
  const low = kwh < model.typical * PROTO_PF_LOW_SHARE;
  const kvah = Math.hypot(kwh, q);
  return {
    kwh,
    kvah,
    peak: kvah * 2,
    peakAt: "",
    lag: leading ? 0 : q,
    lead: leading ? q : 0,
    excess: Math.max(0, q - PROTO_PF_ALLOWANCE * kwh),
    keepP: low ? 0 : kwh,
    keepLag: low || leading ? 0 : q,
    keepLead: low || !leading ? 0 : q,
    slots: 1,
    lowSlots: low ? 1 : 0,
    leadSlots: !low && leading ? 1 : 0,
  };
}

const PROTO_PF_SUMS = ["kwh", "kvah", "lag", "lead", "excess", "keepP", "keepLag", "keepLead", "slots", "lowSlots", "leadSlots"];

// Power factor comes from the totals, never an average of averages. Lagging and leading are not netted off.
// The highest half-hour's kVA is carried up, since that is what the supply has to carry.
function protoPowerSum(label, name, parts, quality) {
  const row = { label, name, quality, peak: null, peakAt: "" };
  PROTO_PF_SUMS.forEach((key) => {
    row[key] = parts.reduce((n, part) => n + (part ? part[key] : 0), 0);
  });
  parts.forEach((part) => {
    if (part && part.peak != null && (row.peak == null || part.peak > row.peak)) {
      row.peak = part.peak;
      row.peakAt = part.peakAt;
    }
  });
  row.pf = row.keepP ? row.keepP / Math.hypot(row.keepP, row.keepLag + row.keepLead) : null;
  row.leading = row.keepLead > row.keepLag;
  return row;
}

function protoPowerRows(meters) {
  const list = protoPowerMeters(meters);
  if (!list.length) return [];
  const span = protoDateSpan();
  const zone = protoChartZone();
  const model = protoPowerModel(list);
  const shape = protoShapeMeters(list);
  const series = list.map((meter) => protoSiteSeries(meter));
  const labels = series[0].map((p) => p.label);
  const names = protoSpanPointNames(span, labels, false);
  const sumAt = (i) => {
    const have = series.map((s) => s[i]).filter((p) => p && p.value != null);
    return {
      kwh: have.length ? have.reduce((n, p) => n + p.value, 0) : null,
      quality: have.some((p) => p.quality === "estimated") ? "estimated" : have.length ? "actual" : "missing",
    };
  };
  if (span.kind === "interval") {
    const day = protoIso(span.from);
    return labels.map((label, i) => {
      const { kwh, quality } = sumAt(i);
      const slot = kwh == null ? null : protoPowerSlot(model, kwh, `${day}|${i}`);
      if (slot) slot.peakAt = `${label} ${zone}`;
      return protoPowerSum(label, `${label} ${zone}`, [slot], quality);
    });
  }
  if (span.kind === "day") {
    return labels.map((label, i) => {
      const { kwh, quality } = sumAt(i);
      if (kwh == null) return protoPowerSum(label, names[i], [], "missing");
      const date = protoAddDays(span.from, i);
      const day = protoIso(date);
      const slots = protoCalendarDayShape(shape, date, kwh).map((v, k) => {
        if (v == null) return null;
        const slot = protoPowerSlot(model, v, `${day}|${k}`);
        slot.peakAt = `${protoDemandSlot(k)} ${zone} on ${names[i]}`;
        return slot;
      });
      return protoPowerSum(label, names[i], slots, quality);
    });
  }
  return labels.map((label, i) => {
    const start = new Date(span.from.getFullYear(), span.from.getMonth() + i, 1);
    const monthEnd = new Date(start.getFullYear(), start.getMonth() + 1, 0);
    const end = monthEnd > span.to ? span.to : monthEnd;
    const days = start > end ? [] : protoWithSpan({ from: start, to: end, kind: "day" }, () => protoPowerRows(list));
    const have = days.filter((row) => row.slots);
    const quality = have.some((row) => row.quality === "estimated") ? "estimated" : have.length ? "actual" : "missing";
    return protoPowerSum(label, label, have, quality);
  });
}

function protoPowerAmount(value, unit) {
  return `${Math.round(value).toLocaleString("en-GB")} ${unit}`;
}

function protoPowerChart(rows, measure) {
  const reactive = measure === "reactive";
  const title = PROTO_POWER_MEASURES.find((item) => item.id === measure)?.name || "Power factor";
  const heading = { title, when: `${protoChartWhen()} ${protoChartZone()}`, tools: protoPowerMeasureSelect(measure) };
  const line = protoChartIsLine();
  const limit = (key, values, names, label, keyName, places, keyTip = "") => ({
    key,
    kind: "limit",
    track: "",
    style: "cap",
    color: "",
    flow: "",
    flat: true,
    label,
    places,
    values,
    qualities: [],
    names,
    nowNames: values.map(() => ""),
    keyName,
    keyTip,
  });
  const chart = () => {
    if (measure === "apparent") {
      const points = rows.map((row) => ({
        label: row.label,
        value: row.slots ? Number(row.kvah.toFixed(1)) : null,
        quality: row.quality,
        unit: "kVAh",
        tipNote: row.slots
          ? `Active energy ${Number(row.kwh.toFixed(1)).toLocaleString("en-GB", { maximumFractionDigits: 1 })} kWh.${row.pf == null ? "" : ` Power factor ${row.pf.toFixed(2)}.`}`
          : "",
      }));
      return line
        ? protoLineChart([{ id: "kvah", ref: title, color: protoIncomingInk(), dash: "", points }], title, { heading, still: true })
        : protoBarChart(points, title, { heading, still: true });
    }
    if (!reactive) {
      const points = rows.map((row) => ({
        label: row.label,
        value: row.pf == null ? null : Number(row.pf.toFixed(2)),
        quality: row.quality,
        unit: "PF",
        tipNote: row.pf == null && row.slots ? PROTO_PF_LOW_NOTE : row.leading ? PROTO_PF_LEAD_NOTE : "",
      }));
      const refs = [
        limit(
          "pf-target",
          points.map(() => PROTO_PF_TARGET),
          points.map(() => "Target"),
          `Target ${PROTO_PF_TARGET}`,
          `Target ${PROTO_PF_TARGET}`,
          2,
          `Aim to keep power factor at ${PROTO_PF_TARGET} or above`
        ),
      ];
      return line
        ? protoLineChart([{ id: "pf", ref: title, color: protoIncomingInk(), dash: "", points }], title, { refs, heading, still: true })
        : protoBarChart(points, title, { refs, heading, still: true });
    }
    const amount = (value) => Number(value.toFixed(1));
    const allowance = rows.map((row) => (row.slots ? amount(row.kwh * PROTO_PF_ALLOWANCE) : null));
    const refs = [
      limit(
        "pf-allowance",
        allowance,
        rows.map(() => "Allowance"),
        "Allowance",
        "Allowance",
        1,
        `Reactive energy up to about ${Math.round(PROTO_PF_ALLOWANCE * 100)}% of kWh before excess charges`
      ),
    ];
    const keyNames = { in: "Lagging", out: "Leading" };
    if (line) {
      const track = (id, ref, color, key) => ({
        id,
        ref,
        color,
        dash: "",
        points: rows.map((row) => ({
          label: row.label,
          value: row.slots ? amount(row[key]) : null,
          quality: row.quality,
          unit: "kVArh",
        })),
      });
      return protoLineChart(
        [track("lag", "Lagging", protoIncomingInk(), "lag"), track("lead", "Leading", protoOutgoingInk(), "lead")],
        title,
        { refs, heading, still: true, dual: true, keyNames }
      );
    }
    const points = rows.map((row) => ({
      label: row.label,
      value: row.slots ? amount(row.lag) : null,
      last: row.slots ? amount(row.lead) : null,
      quality: row.quality,
      lastQuality: row.quality,
      nowLabel: "Lagging",
      lastLabel: "Leading",
      unit: "kVArh",
      spoken: row.slots
        ? `${row.name}. Lagging ${protoPowerAmount(row.lag, "kVArh")}. Leading ${protoPowerAmount(row.lead, "kVArh")}.`
        : `${row.name}. No reading.`,
    }));
    return protoBarChart(points, title, { refs, heading, still: true, dual: true, keyNames });
  };
  return protoWithStore(
    {
      prototypePane: "consumption",
      prototypePaneFilters: [],
      prototypeChartSliceOff: [],
      prototypeChartFlows: ["in", "out"],
      prototypeChartPoint: null,
    },
    chart
  );
}

// Pick power factor, reactive energy or apparent energy. Each shows its graph, then the figures a bill or an engineer would use.
function protoPowerPane(meters) {
  const incoming = protoPowerMeters(meters);
  if (protoNoReadings(incoming)) return protoNoReadingsHtml(incoming);
  const measure = protoPowerMeasure();
  const title = PROTO_POWER_MEASURES.find((item) => item.id === measure)?.name || "Power factor";
  const rows = protoPowerRows(meters);
  const read = rows.filter((row) => row.slots);
  if (!read.length) {
    return `
      <div class="astral-chart-head">
        <div class="astral-chart-heading">
          <p class="astral-chart-title">${escapeHtml(title)}</p>
          <p class="astral-chart-when">${escapeHtml(`${protoChartWhen()} ${protoChartZone()}`)}</p>
        </div>
        <div class="astral-chart-nav">${protoPowerMeasureSelect(measure)}</div>
      </div>
      <p class="astral-banner">${escapeHtml(title)} comes from incoming electricity meters. There are none in this view.</p>
    `;
  }
  const span = protoDateSpan();
  const grain = PROTO_PF_GRAIN[span.kind] || PROTO_PF_GRAIN.day;
  const count = (n, words = grain) => `${n.toLocaleString("en-GB")} ${n === 1 ? words.one : words.many}`;
  const halves = PROTO_PF_GRAIN.interval;
  const total = protoPowerSum("", "", read, "");
  const way = (row) => (row.leading ? "leading" : "lagging");
  const at = (row) => (grain.one === "half hour" ? `At ${row.name}` : grain.one === "day" ? `On ${row.name}` : `In ${row.name}`);
  let figures;
  if (measure === "apparent") {
    const sites = new Set(incoming.map((meter) => meter.site || ""));
    const kva = sites.size === 1 ? protoSiteCapacityKva(incoming[0]) : 0;
    const peak = read.reduce((best, row) => (row.peak != null && (!best || row.peak > best.peak) ? row : best), null);
    figures = [
      { name: "Apparent energy", value: protoPowerAmount(total.kvah, "kVAh"), note: "Calculated from kWh and kVArh" },
      { name: "Active energy", value: protoPowerAmount(total.kwh, "kWh"), note: "The part that does useful work" },
      {
        name: "Extra from reactive energy",
        value: `${total.kwh ? Math.round((total.kvah / total.kwh - 1) * 100) : 0}%`,
        note: "More current than the work needs",
      },
      ...(peak
        ? [
            {
              name: "Highest half-hour",
              value: `${Number(peak.peak.toFixed(1)).toLocaleString("en-GB", { maximumFractionDigits: 1 })} kVA`,
              note: `At ${peak.peakAt}`,
            },
          ]
        : []),
      ...(peak && kva
        ? [
            {
              name: "Highest half-hour against site capacity",
              value: `${Math.round((peak.peak / kva) * 100)}%`,
              note: `Site capacity ${kva.toLocaleString("en-GB")} kVA. Both are in kVA, so no power factor is assumed`,
            },
          ]
        : []),
    ];
  } else if (measure === "reactive") {
    figures = [
      { name: "Lagging", value: protoPowerAmount(total.lag, "kVArh"), note: "From motors, transformers and other inductive loads" },
      { name: "Leading", value: protoPowerAmount(total.lead, "kVArh"), note: "From correction equipment or long cables at light load" },
      {
        name: "Over the allowance",
        value: protoPowerAmount(total.excess, "kVArh"),
        note: "An estimate. Allowances vary by network operator",
      },
      { name: "Electricity used", value: protoPowerAmount(total.kwh, "kWh"), note: "Incoming electricity" },
    ];
  } else {
    const shown = read.filter((row) => row.pf != null);
    const below = shown.filter((row) => Number(row.pf.toFixed(2)) < PROTO_PF_TARGET).length;
    const low = shown.length ? shown.reduce((best, row) => (row.pf < best.pf ? row : best)) : null;
    figures = [
      {
        name: "Power factor",
        value: total.pf == null ? "Not shown" : `${total.pf.toFixed(2)} ${way(total)}`,
        note: total.pf == null ? "Use was too low" : "From total kWh and kVArh, not an average",
      },
      ...(low ? [{ name: `Lowest ${grain.adj} power factor`, value: `${low.pf.toFixed(2)} ${way(low)}`, note: at(low) }] : []),
      { name: `Below ${PROTO_PF_TARGET}`, value: count(below), note: `Out of ${count(shown.length)}` },
      { name: "Leading", value: count(total.leadSlots, halves), note: "Often a sign of too much correction" },
      { name: "Left out for low use", value: count(total.lowSlots, halves), note: `Out of ${count(total.slots, halves)}` },
    ];
  }
  const spec = PROTO_BREAKDOWN_FOLDS.summary;
  const summary = protoAccordion({
    id: spec.id,
    open: Boolean(store[spec.field]),
    name: "Summary",
    note: protoRangeWords(span.from, span.to),
    attr: 'data-proto-breakdown="summary"',
    modifier: "astral-breakdown",
    clipClass: "astral-breakdown-clip",
    inner: `<div class="astral-pane-summary">${protoWeatherFigureGroup("", figures)}</div>`,
  });
  return `
    ${protoPowerChart(rows, measure)}
    ${summary}
  `;
}
// Demand is how fast electricity is drawn, in kW. A half-hour's kWh doubled gives its kW.
// A day or month shows its highest half-hour, because that is what a supply has to carry.
function protoDemandSlot(i) {
  return `${String(Math.floor(i / 2)).padStart(2, "0")}.${i % 2 ? "30" : "00"}`;
}

function protoDemandRows(meters) {
  const list = protoPowerMeters(meters);
  if (!list.length) return [];
  const span = protoDateSpan();
  const zone = protoChartZone();
  const shape = protoShapeMeters(list);
  const series = list.map((meter) => protoSiteSeries(meter));
  const labels = series[0].map((p) => p.label);
  const names = protoSpanPointNames(span, labels, false);
  const sumAt = (i) => {
    const have = series.map((s) => s[i]).filter((p) => p && p.value != null);
    return {
      kwh: have.length ? have.reduce((n, p) => n + p.value, 0) : null,
      quality: have.some((p) => p.quality === "estimated") ? "estimated" : have.length ? "actual" : "missing",
    };
  };
  if (span.kind === "interval") {
    return labels.map((label, i) => {
      const { kwh, quality } = sumAt(i);
      const kw = kwh == null ? null : kwh * 2;
      const at = `${label} ${zone}`;
      return { label, kw, kwh, hours: kwh == null ? 0 : 0.5, quality, peakAt: at, low: kw, lowAt: at };
    });
  }
  if (span.kind === "day") {
    return labels.map((label, i) => {
      const { kwh, quality } = sumAt(i);
      const empty = { label, kw: null, kwh: null, hours: 0, quality: "missing", peakAt: "", low: null, lowAt: "" };
      if (kwh == null) return empty;
      const slots = protoCalendarDayShape(shape, protoAddDays(span.from, i), kwh);
      let peak = -1;
      let low = -1;
      slots.forEach((v, k) => {
        if (v == null) return;
        if (peak < 0 || v > slots[peak]) peak = k;
        if (low < 0 || v < slots[low]) low = k;
      });
      if (peak < 0) return empty;
      return {
        label,
        kw: slots[peak] * 2,
        kwh,
        hours: 24,
        quality,
        peakAt: `${protoDemandSlot(peak)} ${zone} on ${names[i]}`,
        low: slots[low] * 2,
        lowAt: `${protoDemandSlot(low)} ${zone} on ${names[i]}`,
      };
    });
  }
  return labels.map((label, i) => {
    const start = new Date(span.from.getFullYear(), span.from.getMonth() + i, 1);
    const monthEnd = new Date(start.getFullYear(), start.getMonth() + 1, 0);
    const end = monthEnd > span.to ? span.to : monthEnd;
    const days = start > end ? [] : protoWithSpan({ from: start, to: end, kind: "day" }, () => protoDemandRows(list));
    const have = days.filter((row) => row.kw != null);
    if (!have.length) return { label, kw: null, kwh: null, hours: 0, quality: "missing", peakAt: "", low: null, lowAt: "" };
    const top = have.reduce((best, row) => (row.kw > best.kw ? row : best));
    const bottom = have.reduce((best, row) => (row.low < best.low ? row : best));
    return {
      label,
      kw: top.kw,
      kwh: have.reduce((n, row) => n + row.kwh, 0),
      hours: have.reduce((n, row) => n + row.hours, 0),
      quality: have.some((row) => row.quality === "estimated") ? "estimated" : "actual",
      peakAt: top.peakAt,
      low: bottom.low,
      lowAt: bottom.lowAt,
    };
  });
}

function protoDemandPoints(rows) {
  return rows.map((row) => ({
    label: row.label,
    value: row.kw == null ? null : Number(row.kw.toFixed(1)),
    quality: row.quality,
    unit: "kW",
  }));
}

// Demand takes the same Chart settings as Consumption. Site capacity is an overlay here, because both are in kW.
function protoDemandChart(rows, meters) {
  const label = "Demand";
  const points = protoDemandPoints(rows);
  const remake = () => ({ points: protoDemandPoints(protoDemandRows(meters)) });
  const same = (list) => list;
  const capacity = protoCapacityRefs(meters, points);
  if (protoChartIsLine()) {
    const lineRefs = (again) => [{ id: "demand", track: "demand", color: protoIncomingInk(), points: again.points || [] }];
    const pair = protoDateCompareSpan() ? protoDateCompareLines(points, remake, meters, false, false, label, same) : null;
    if (pair) {
      return protoLineChart(pair.tracks, label, {
        dual: true,
        datePair: pair.flow,
        keyNames: pair.keyNames,
        zoneMeters: meters,
        refs: [...protoProfileRefs(remake, lineRefs), ...capacity],
        weekends: true,
      });
    }
    return protoLineChart([{ id: "demand", ref: label, color: protoIncomingInk(), dash: "", points }], label, {
      zoneMeters: meters,
      refs: [...protoDateCompareRefs(remake, lineRefs), ...protoProfileRefs(remake, lineRefs), ...capacity],
      weekends: true,
    });
  }
  const barRefs = (again) => [{ id: "total", points: again.points || [] }];
  const profileRefs = protoProfileRefs(remake, barRefs);
  if (protoDateCompareSpan()) {
    const pair = protoDateCompareBars(points, remake, same, "in", false);
    if (pair) {
      return protoBarChart(pair.points, label, {
        datePair: "in",
        zoneMeters: meters,
        refs: [...profileRefs, ...capacity],
        keyNames: pair.keyNames,
        weekends: true,
      });
    }
  }
  return protoBarChart(points, label, {
    zoneMeters: meters,
    refs: [...protoDateCompareRefs(remake, barRefs), ...profileRefs, ...capacity],
    weekends: true,
  });
}

// The graph in kW, then the figures Data Vision users look for: highest, average and lowest demand, and the total used.
function protoDemandPane(meters) {
  const incoming = protoPowerMeters(meters);
  if (protoNoReadings(incoming)) return protoNoReadingsHtml(incoming);
  const rows = protoDemandRows(meters);
  const have = rows.filter((row) => row.kw != null);
  if (!have.length) {
    return `
      <div class="astral-chart-head">
        <div class="astral-chart-heading">
          <p class="astral-chart-title">Demand</p>
          <p class="astral-chart-when">${escapeHtml(`${protoChartWhen()} ${protoChartZone()}`)}</p>
        </div>
      </div>
      <p class="astral-banner">Demand comes from incoming electricity meters. There are none in this view.</p>
    `;
  }
  const span = protoDateSpan();
  const kw = (value) => `${Number(value.toFixed(1)).toLocaleString("en-GB", { maximumFractionDigits: 1 })} kW`;
  const top = have.reduce((best, row) => (row.kw > best.kw ? row : best));
  const bottom = have.reduce((best, row) => (row.low < best.low ? row : best));
  const kwh = have.reduce((n, row) => n + row.kwh, 0);
  const hours = have.reduce((n, row) => n + row.hours, 0);
  const figures = [
    { name: "Highest demand", value: kw(top.kw), note: `At ${top.peakAt}` },
    { name: "Average demand", value: kw(hours ? kwh / hours : 0), note: "Total used divided by the hours with readings" },
    { name: "Lowest demand", value: kw(bottom.low), note: `At ${bottom.lowAt}` },
    { name: "Total used", value: `${Math.round(kwh).toLocaleString("en-GB")} kWh`, note: "Incoming electricity" },
  ];
  if (!protoCapacityBlockedFor(meters)) {
    const kva = protoSiteCapacityKva(meters[0]);
    const at = protoCapacityPf(meters);
    const capKw = protoCapacityKw(kva, at.pf);
    figures.push({
      name: "Highest demand against site capacity",
      value: `${Math.round((top.kw / capKw) * 100)}%`,
      note: `Site capacity ${kva.toLocaleString("en-GB")} kVA, about ${protoFormatAmount(capKw, 1)} kW ${protoCapacityPfWords(at)}`,
    });
  }
  const spec = PROTO_BREAKDOWN_FOLDS.summary;
  const summary = protoAccordion({
    id: spec.id,
    open: Boolean(store[spec.field]),
    name: "Summary",
    note: protoRangeWords(span.from, span.to),
    attr: 'data-proto-breakdown="summary"',
    modifier: "astral-breakdown",
    clipClass: "astral-breakdown-clip",
    inner: `<div class="astral-pane-summary">${protoWeatherFigureGroup("", figures)}</div>`,
  });
  return `
    ${protoDemandChart(rows, meters)}
    ${summary}
  `;
}

function protoMeterFacts(meter, profile = protoMeterProfile(meter?.id)) {
  const kind = protoMeterKind(meter);
  const site = protoSiteByMeter(meter?.id);
  return {
    ref: protoMeterRef(meter),
    refName: kind === "water" ? "Serial" : kind === "gas" ? "MPRN" : "MPAN",
    commodity: kind === "water" ? "Water" : kind === "gas" ? "Gas" : "Electricity",
    channel: protoChannelLabel(meter) || "In",
    hours: protoClockShow(protoHoursSummary(profile) || meter?.hours || "Unknown"),
    tou: protoTouSummary(profile) || meter?.tou || "Unknown",
    tariff: meter?.tariff || "Unknown",
    use: meter?.use24h || "None",
    site: site?.name || meter?.site || "",
  };
}

function protoOpenMeter() {
  const id = String(store.prototypeMeterOpen || "");
  if (!id || id === "none") return null;
  return protoMeters().find((item) => item.id === id) || null;
}

function protoMeterOpenId(meters) {
  const open = protoOpenMeter();
  if (!open) return "";
  const ids = (meters || []).map((item) => item.id).filter(Boolean);
  return ids.includes(open.id) ? open.id : "";
}

